/** Assistant adapter over the screen's dispatcher and admitted handler host. No module is reloaded here. */
import type { AdminSurfaceActionOutcome } from './protocol.js';
import { ToolInputError, requireInputRecord } from '@jini-ai/core';
import type { AgentPluginAdditionalTool, AgentPluginToolInvocation } from '../lifecycle/tools/projection.js';
import { createAdminSurfaceActionDispatcher, type AdminSurfaceActionHandler } from './action-dispatcher.js';
import { exceedsAdminSurfacePayloadLimit, validateAdminSurfaceActionValue } from './action-schema.js';
import type { AdminSurfaceAction, AdminSurfaceDescriptor } from './descriptor.js';
import type { AdminSurfaceHandlerContext } from './surface-handlers.js';

/** Admin tools always act for an authenticated principal, supplied by the registry. */
export interface AdminSurfaceToolContext extends AdminSurfaceHandlerContext {
  readonly principalId: string;
}

/** The host binds this from active, trusted surface contributions and its existing handler host. */
export interface AdminSurfaceToolSource {
  readonly pluginId: string;
  readonly descriptor: AdminSurfaceDescriptor;
}

/** Checks the tool envelope and delegates payload validation to the screen's schema owner.
 * @throws ToolInputError without echoing input values. @complexity O(p) payload size. */
function checkedPayload(required: { readonly input: unknown; readonly action: AdminSurfaceAction }, _optional: Record<string, never> = {}): unknown {
  const { input, action } = required;
  const record = requireInputRecord({ input });
  if (Object.keys(record).length !== 1 || !Object.hasOwn(record, 'payload') || exceedsAdminSurfacePayloadLimit({ payload: record.payload })
    || validateAdminSurfaceActionValue({ schema: action.input, value: record.payload }) !== null) {
    throw new ToolInputError({ message: 'Supply payload matching the declared admin action schema.' });
  }
  return record.payload;
}

/**
 * Projects every declared surface action into the existing plugin-tool contract. All actions use a
 * `payload` envelope (including scalar/array actions), and the SAME dispatcher and handler host as
 * the screen. The host supplies fresh authorization/admission before each call, including after a
 * confirmation wait. Browser flows return their result and any host-issued URLs; this seam cannot open a browser.
 * @param required.authorize - Must enforce the screen action permission and fresh trusted admission.
 * @param optional.run - Request-local result decoration, e.g. collecting host-issued sign-in URLs.
 * @returns Contributions for `createAgentPluginToolProjection.sync({ additionalTools })`.
 * @complexity O(s + a) surfaces and actions, bounded by the descriptor parser; dispatch O(p) + handler.
 */
export function buildAdminSurfaceActionTools(required: {
  readonly surfaces: readonly AdminSurfaceToolSource[];
  readonly handlersFor: (input: { readonly pluginId: string; readonly surfaceId: string }) => Readonly<Record<string, AdminSurfaceActionHandler<AdminSurfaceToolContext>>>;
  readonly authorize: (input: { readonly context: AdminSurfaceToolContext }) => Promise<void>;
}, optional: { readonly run?: (input: { readonly dispatch: () => Promise<AdminSurfaceActionOutcome> }) => Promise<unknown> } = {}): readonly AgentPluginAdditionalTool[] {
  return required.surfaces.flatMap(({ pluginId, descriptor }) => descriptor.actions.map((action): AgentPluginAdditionalTool => {
    const name = `${descriptor.id.replace(/-/g, '_')}_${action.name.replace(/-/g, '_')}`;
    return {
      pluginId,
      tool: {
        name, description: `${descriptor.title}: ${action.name}. Browser sign-in actions return a URL to show the user.`,
        effect: action.effect ?? 'write',
        inputSchema: { type: 'object', properties: { payload: action.input }, required: ['payload'], additionalProperties: false },
        async handler({ auth, input }: AgentPluginToolInvocation) {
          if (!auth.principalId) throw new ToolInputError({ message: 'Admin actions require an authenticated principal.' });
          const context: AdminSurfaceToolContext = { ...auth, principalId: auth.principalId, pluginId, surfaceId: descriptor.id };
          await required.authorize({ context });
          const payload = checkedPayload({ input, action });
          const dispatcher = createAdminSurfaceActionDispatcher({ descriptor, handlers: required.handlersFor({ pluginId, surfaceId: descriptor.id }) });
          const dispatch = () => dispatcher.dispatch({ action: action.name, payload, context });
          return optional.run ? optional.run({ dispatch }) : dispatch();
        },
      },
      describeAffectedResources({ input }) {
        checkedPayload({ input, action });
        return [`${descriptor.title}: ${action.name}`];
      },
    };
  }));
}

src/admin-surfaces/callback-field-inbox..source:
/**
 * @file A one-time, bounded holding place for the extra fields a provider returns on a completed
 * sign-in (for example the id of a resource the person picked during consent), between the host's
 * callback route and the plugin handler that asked for the sign-in.
 *
 * Why it exists: the callback arrives on a host route the plugin never sees, but the plugin's
 * surface handler is the one that must read and verify those fields. The host deposits them only
 * after the sign-in completed successfully; the plugin's `connections.takeCallbackFields` takes them
 * exactly once, and only under the same workspace, plugin, connection and attempt id, so another
 * plugin or a second read gets `null`. Entries expire and the inbox is capped, so an abandoned
 * sign-in cannot grow memory. It is in-process: a host that completes sign-ins on another process
 * implements the same two methods over its own store.
 */

export interface AdminSurfaceCallbackFieldKey {
  readonly workspaceId: string;
  readonly pluginId: string;
  readonly connectionId: string;
  readonly attemptId: string;
}

/** How long a deposit waits to be taken: the sign-in attempt lifetime. */
const INBOX_TTL_MS = 10 * 60 * 1000;
/** Cap; the oldest entry is dropped first when full. */
const INBOX_MAX_ENTRIES = 256;

/** NUL cannot appear in any of these ids, so the joined key is unambiguous. */
const keyOf = (key: AdminSurfaceCallbackFieldKey) => [key.workspaceId, key.pluginId, key.connectionId, key.attemptId].join('\u0000');

/**
 * @param required.now - Clock in epoch milliseconds (injected so expiry is testable).
 * @returns `deposit` (host callback route, after a successful completion) and `take` (consume-once).
 * @complexity deposit is O(e) to sweep expired entries; take is O(1).
 */
export function createAdminSurfaceCallbackInbox(
  required: { readonly now: () => number },
  _optional: Record<string, never> = {},
) {
  // Map iteration order is insertion order, so the first entry is always the oldest.
  const entries = new Map<string, { readonly fields: Readonly<Record<string, string>>; readonly expiresAt: number }>();

  function sweep(nowMs: number): void {
    for (const [key, entry] of entries) if (entry.expiresAt <= nowMs) entries.delete(key);
    while (entries.size >= INBOX_MAX_ENTRIES) entries.delete(entries.keys().next().value!);
  }

  return {
    /** Holds a completed sign-in's callback fields (call it only after the exchange succeeded). */
    deposit(input: AdminSurfaceCallbackFieldKey & { readonly fields: Readonly<Record<string, string>> }, _options: Record<string, never> = {}): void {
      const nowMs = required.now();
      sweep(nowMs);
      entries.set(keyOf(input), { fields: Object.freeze({ ...input.fields }), expiresAt: nowMs + INBOX_TTL_MS });
    },
    /** The fields, removed on the first read; `null` when never deposited, already taken, expired or keyed differently. */
    take(input: AdminSurfaceCallbackFieldKey, _options: Record<string, never> = {}): Readonly<Record<string, string>> | null {
      const key = keyOf(input);
      const entry = entries.get(key);
      if (entry === undefined) return null;
      entries.delete(key);
      return entry.expiresAt > required.now() ? entry.fields : null;
    },
  };
}

src/admin-surfaces/capability-declaratio.source:
/**
 * @file Parses the capability declarations a surface with a `handlerModule` may make: which of the
 * plugin's own connections its handlers administer (with the per-start parameters and callback
 * fields each may use), which public configuration values the host may hand its handlers, and which
 * of the plugin's delivery adapters' form-delivery bindings they manage (`./delivery-bindings.ts`).
 *
 * Why they are declared, not requested at run time: the surfaces file is part of the shipped,
 * digest-checked package, so these lists are the trusted allowlists the admin-surface capability
 * session (`./surface-capabilities.ts`) enforces. A handler can never reach a connection, a start
 * parameter, a callback field or a config value its surface did not declare. Config names that look
 * like secrets are refused here, so a secret can never become "public config" by a naming slip.
 */

/** One connection a surface's handlers may administer. `id` is the plugin's own connection id, never a ref. */
export interface AdminSurfaceConnectionDeclaration {
  readonly id: string;
  /** Authorization parameters a handler may set for one sign-in (the connection must also allow them). */
  readonly startParams: readonly string[];
  /** Provider callback fields a handler may take once after a completed sign-in. */
  readonly callbackFields: readonly string[];
}

export interface AdminSurfaceCapabilityDeclarations {
  readonly connections?: readonly AdminSurfaceConnectionDeclaration[];
  readonly publicConfig?: readonly string[];
  /** Delivery adapter ids whose bindings the handlers manage. Jini checks only the shape; the host
   *  checks that each is an adapter this same plugin contributes. */
  readonly deliveryAdapters?: readonly string[];
  /** Read-only form discovery; no form contents, submissions or mutation access. */
  readonly forms?: readonly 'list'[];
}

type Entry = Readonly<Record<string, unknown>>;

/** Same shapes the API-connection descriptor accepts for connection ids and parameter names. */
const CONNECTION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
const FIELD_NAME_PATTERN = /^[A-Za-z0-9_.-]{1,64}$/;
/**
 * Copy of the OAuth core's `isCallbackFieldName` pattern (`@jini-ai/oauth` loopback-callback.ts is
 * the source of truth; agent-plugins does not depend on it). The descriptor applies the full check,
 * including the reserved protocol names, so a field passing here but reserved there is never declared.
 */
const CALLBACK_FIELD_NAME_PATTERN = /^[A-Za-z][A-Za-z0-9_.-]{0,63}$/;
/** Environment-style names, so a host can map them to its own config without translation. */
const CONFIG_NAME_PATTERN = /^[A-Z][A-Z0-9_]{0,63}$/;
/** Name parts that mark a credential. A plugin's public values never need one of them. */
const SECRET_NAME_PATTERN = /SECRET|TOKEN|PASSWORD|PASSWD|PRIVATE|CREDENTIAL|COOKIE|SESSION|SIGNING/;
/** The host's destination-id shape (lowercase hyphenated, at most 64), so a declared id can match one. */
const ADAPTER_ID_PATTERN = /^(?=.{1,64}$)[a-z0-9]+(?:-[a-z0-9]+)*$/;
const MAX_CONNECTIONS = 4;
const MAX_DELIVERY_ADAPTERS = 8;
const MAX_FIELDS = 8;
const MAX_CONFIG_NAMES = 16;

const isPlainObject = (value: unknown): value is Entry => typeof value === 'object' && value !== null && !Array.isArray(value);

/** A bounded, de-duplicated list of names matching `pattern`, or why not. @complexity O(n) names. */
function parseNames(value: unknown, required: { readonly pattern: RegExp; readonly max: number; readonly at: string }): readonly string[] | string {
  const { pattern, max, at } = required;
  if (!Array.isArray(value) || value.length > max) return `${at} must be an array of at most ${max}`;
  const bad = value.findIndex((name, index) => typeof name !== 'string' || !pattern.test(name) || value.indexOf(name) !== index);
  return bad === -1 ? (value as string[]) : `${at}[${bad}] must be a unique name matching ${pattern.source}`;
}

function parseConnection(entry: unknown, at: string): AdminSurfaceConnectionDeclaration | string {
  if (!isPlainObject(entry)) return `${at} must be an object`;
  if (typeof entry.id !== 'string' || !CONNECTION_ID_PATTERN.test(entry.id)) return `${at}.id must be a short connection id`;
  const startParams = parseNames(entry.startParams ?? [], { pattern: FIELD_NAME_PATTERN, max: MAX_FIELDS, at: `${at}.startParams` });
  if (typeof startParams === 'string') return startParams;
  const callbackFields = parseNames(entry.callbackFields ?? [], { pattern: CALLBACK_FIELD_NAME_PATTERN, max: MAX_FIELDS, at: `${at}.callbackFields` });
  return typeof callbackFields === 'string' ? callbackFields : { id: entry.id, startParams, callbackFields };
}

function parseConnections(value: unknown, at: string): readonly AdminSurfaceConnectionDeclaration[] | string {
  if (!Array.isArray(value) || value.length > MAX_CONNECTIONS) return `${at} must be an array of at most ${MAX_CONNECTIONS}`;
  const connections: AdminSurfaceConnectionDeclaration[] = [];
  for (const [index, entry] of value.entries()) {
    const parsed = parseConnection(entry, `${at}[${index}]`);
    if (typeof parsed === 'string') return parsed;
    if (connections.some((seen) => seen.id === parsed.id)) return `${at}[${index}].id '${parsed.id}' is declared twice`;
    connections.push(parsed);
  }
  return connections;
}

function parsePublicConfig(value: unknown, at: string): readonly string[] | string {
  const names = parseNames(value, { pattern: CONFIG_NAME_PATTERN, max: MAX_CONFIG_NAMES, at });
  if (typeof names === 'string') return names;
  const secret = names.findIndex((name) => SECRET_NAME_PATTERN.test(name));
  return secret === -1 ? names : `${at}[${secret}] names a secret; public config may only hold values that are safe to show`;
}

function parseDeliveryAdapters(value: unknown, at: string): readonly string[] | string {
  return parseNames(value, { pattern: ADAPTER_ID_PATTERN, max: MAX_DELIVERY_ADAPTERS, at });
}

/** Only the read operation can be granted; unknown operations fail admission. */
function parseForms(value: unknown, at: string): readonly string[] | string {
  return parseNames(value, { pattern: /^list$/, max: 1, at });
}

/** Each declaration's parser, in the order refusals are reported. */
const DECLARATION_PARSERS = [
  ['connections', parseConnections], ['publicConfig', parsePublicConfig], ['deliveryAdapters', parseDeliveryAdapters], ['forms', parseForms],
] as const satisfies readonly (readonly [keyof AdminSurfaceCapabilityDeclarations, (value: unknown, at: string) => unknown])[];

/**
 * The surface's capability declarations, with keys present only when declared (an undeclared list
 * adds no key, so existing descriptors parse unchanged), or why the file is refused.
 * @complexity O(c * f + n + d) connections with their fields, config names and delivery adapters; every list is capped.
 */
export function parseAdminSurfaceCapabilityDeclarations(required: { readonly entry: Entry; readonly at: string }, _optional: Record<string, never> = {}): AdminSurfaceCapabilityDeclarations | string {
  const { entry, at } = required;
  const declarations: Record<string, unknown> = {};
  for (const [name, parse] of DECLARATION_PARSERS) {
    if (entry[name] === undefined) continue;
    const parsed = parse(entry[name], `${at}.${name}`);
    if (typeof parsed === 'string') return parsed;
    declarations[name] = parsed;
  }
  return declarations as AdminSurfaceCapabilityDeclarations;
}

