src/admin-surfaces/surface-capabilities..source:
/**
 * @file The host capability ports a plugin's admin-surface handlers receive, and the per-call
 * session that wraps them. Jini defines the shapes and the checks; the host implements the ports
 * (connections backed by its API-connection service, state by its own store, public config by its
 * own settings) and Jini never names a provider.
 *
 * Why surfaces get more than tools: account actions (connect, reconnect, switch account, disconnect)
 * and saving a chosen resource are admin actions a person takes on a settings screen, so they exist
 * here and never on the executable-tool port. Why every check sits here and not only in the host:
 * the surfaces file is the shipped, digest-checked allowlist, so the session refuses anything the
 * surface did not declare (a connection, a start parameter, a callback field, a config name) before
 * the host sees it, and a host that answers with more than the port promises (a connection ref, raw
 * scopes, undeclared callback fields) is cut back to the declared shape. Like the tool session it
 * revokes everything once the plugin is disabled and withholds results and errors that mention a
 * token the plugin obtained (in this call, an earlier one, or one of its tools); it also refuses to persist
 * such a token in plugin state.
 */
import {
  checkedStateKey, guardSharedCapabilities, guardStateReader, openCapabilityGate,
  type AgentPluginCapabilityGate, type AgentPluginStateReader, type AgentPluginStateValue, type AgentPluginToolCapabilities, type AgentPluginToolCapabilityScope,
  type IssuedTokenMemory,
} from '../lifecycle/tools/capabilities.js';
import type { AdminSurfaceCapabilityDeclarations, AdminSurfaceConnectionDeclaration } from './capability-declarations.js';
import { guardDeliveryBindings, type AdminSurfaceDeliveryBindings } from './delivery-bindings.js';
import { storedStateValue } from './settings-value.js';

// Moved to `./settings-value.ts` so delivery-binding config shares the exact checks; re-exported so callers keep importing them here.
export { ADMIN_SURFACE_STATE_LIMITS, STATE_CREDENTIAL_MESSAGE } from './settings-value.js';

/** Mirrors the API-connection lifecycle (`ApiConnectionStatus`); only `connected` serves access tokens. */
export type AdminSurfaceConnectionState = 'connected' | 'reconnect-required' | 'revocation-pending' | 'disconnected';

/**
 * The API-connection start intent each account action maps to (`ApiConnectionIntent` in
 * `@jini-ai/integrations/api-connections`, mirrored because agent-plugins does not depend on it), so a
 * host passes `ADMIN_SURFACE_ACTION_INTENTS[action]` straight to `start`. `reconnect` and `add-scopes`
 * are a same-account `connect` with the scope sets the handler passes (`add-scopes` re-consents for
 * more of them); `switch` stages another account.
 */
export const ADMIN_SURFACE_ACTION_INTENTS = Object.freeze({
  connect: 'connect', reconnect: 'connect', switch: 'switch-account', 'add-scopes': 'connect',
} as const);
export type AdminSurfaceConnectionAction = keyof typeof ADMIN_SURFACE_ACTION_INTENTS;
/**
 * The honest remote outcome of a disconnect, the same values as `ApiConnectionRemoteRevocation`:
 * never `confirmed` unless the provider confirmed it.
 */
export type AdminSurfaceRevocationOutcome = 'confirmed' | 'pending' | 'not-needed';

/** Token-free status. Scope sets are the plugin's own ids, never raw provider scopes. */
export interface AdminSurfaceConnectionStatus {
  readonly connectionId: string;
  readonly status: AdminSurfaceConnectionState;
  readonly accountLabel: string | null;
  readonly grantedScopeSetIds: readonly string[];
  /** The account a staged switch would move to, awaiting `confirmSwitch`. */
  readonly pendingSwitchAccountLabel: string | null;
  /** Why the latest sign-in did not complete and what to do next, as the HOST's own lowercase
   *  hyphenated codes (for example `access-denied` / `reconnect`), never provider text; `null` when
   *  the latest attempt succeeded or none is recorded. A value that is not a safe code becomes `null`. */
  readonly lastSignInAttempt: AdminSurfaceSignInAttempt | null;
}

/** The outcome codes of a sign-in attempt that did not complete. */
export interface AdminSurfaceSignInAttempt {
  readonly code: string;
  readonly nextAction: string;
}

/** A sign-in the person opens (a button on hosted, the system browser on desktop). */
export interface AdminSurfaceAuthorizationStart {
  readonly authorizationUrl: string;
  /** Opaque id for `takeCallbackFields` once the sign-in completed: the connection service's attempt
   *  id, never the authorization `state`. */
  readonly attemptId: string;
  readonly expiresAt: string;
}

export interface AdminSurfaceConnections {
  /** A fresh access token for one of the surface's declared connections; never a refresh token. */
  getAccessToken(required: { readonly connectionId: string }, optional?: Record<string, never>): Promise<string>;
  status(required: { readonly connectionId: string }, optional?: Record<string, never>): Promise<AdminSurfaceConnectionStatus>;
  begin(
    required: { readonly connectionId: string; readonly action: AdminSurfaceConnectionAction },
    optional?: { readonly scopeSetIds?: readonly string[]; readonly startParams?: Readonly<Record<string, string>> },
  ): Promise<AdminSurfaceAuthorizationStart>;
  confirmSwitch(required: { readonly connectionId: string }, optional?: Record<string, never>): Promise<AdminSurfaceConnectionStatus>;
  cancelSwitch(required: { readonly connectionId: string }, optional?: Record<string, never>): Promise<AdminSurfaceConnectionStatus>;
  disconnect(required: { readonly connectionId: string }, optional?: Record<string, never>): Promise<AdminSurfaceConnectionStatus & { readonly revocation: AdminSurfaceRevocationOutcome }>;
  /** The declared callback fields of a completed sign-in, once; `null` when absent, taken or not completed.
   *  Still untrusted: verify them through the provider's API before saving anything. */
  takeCallbackFields(required: { readonly connectionId: string; readonly attemptId: string }, optional?: Record<string, never>): Promise<Readonly<Record<string, string>> | null>;
}

export type AdminSurfaceStateValue = AgentPluginStateValue;

/** Plugin- and workspace-scoped JSON values (the host keys them by the session's scope). The plugin's
 *  tools read the same store through the read-only `AgentPluginStateReader`; only surfaces write. */
export interface AdminSurfaceState extends AgentPluginStateReader {
  set(required: { readonly key: string; readonly value: AdminSurfaceStateValue }, optional?: Record<string, never>): Promise<void>;
  delete(required: { readonly key: string }, optional?: Record<string, never>): Promise<void>;
}

/** Host-supplied public values (an app id, a browser key) for names the surface declares; `null` when unset. */
export interface AdminSurfacePublicConfig {
  get(required: { readonly name: string }, optional?: Record<string, never>): Promise<string | null>;
}

/** Only form identity and display text, never fields, recipients or submission data. */
export interface AdminSurfaceForm {
  readonly slug: string;
  readonly title: string;
}

/** Workspace-scoped discovery. The session returns at most 200 choices; titles are capped at 1024 characters. */
export interface AdminSurfaceForms {
  list(required: Record<string, never>, optional?: Record<string, never>): Promise<readonly AdminSurfaceForm[]>;
}

export type AdminSurfaceCapabilities = Pick<AgentPluginToolCapabilities, 'http' | 'limiter' | 'artifacts'> & {
  readonly connections: AdminSurfaceConnections;
  readonly state: AdminSurfaceState;
  readonly publicConfig: AdminSurfacePublicConfig;
  /** The workspace's form-delivery bindings (`./delivery-bindings.ts`). Optional for the host; a handler
   *  gets it only when its surface declares `deliveryAdapters` and the host provides it. */
  readonly deliveryBindings?: AdminSurfaceDeliveryBindings;
  /** Absent unless both the host supplies it and this surface declares `forms: ["list"]`. */
  readonly forms?: AdminSurfaceForms;
};

/** Host port: builds one call's capabilities for the loaded plugin, workspace and admin principal. */
export type AdminSurfaceCapabilitiesPort = (required: AgentPluginToolCapabilityScope, optional?: Record<string, never>) => AdminSurfaceCapabilities;

const ACTIONS: readonly string[] = Object.keys(ADMIN_SURFACE_ACTION_INTENTS);
const SCOPE_SET_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
const ATTEMPT_ID_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_SCOPE_SETS = 16;
const MAX_START_PARAM_LENGTH = 2048;

/** Names in messages come from plugin code: cut them so a message stays a message. */
const named = (value: unknown) => String(value).slice(0, 64);
const isRecord = (value: unknown): value is Readonly<Record<string, unknown>> => typeof value === 'object' && value !== null && !Array.isArray(value);

function declaredConnection(declared: readonly AdminSurfaceConnectionDeclaration[], connectionId: unknown): AdminSurfaceConnectionDeclaration {
  const found = declared.find((connection) => connection.id === connectionId);
  if (found === undefined) throw new Error(`This admin surface does not declare connection '${named(connectionId)}', so its handlers cannot use it. Declare it in the surface's connections.`);
  return found;
}

/** A copy of the start parameters, every name declared for this connection and every value a bounded string. @complexity O(p). */
function checkedStartParams(connection: AdminSurfaceConnectionDeclaration, startParams: unknown): Readonly<Record<string, string>> {
  if (!isRecord(startParams)) throw new Error('Start parameters must be an object of strings.');
  for (const [name, value] of Object.entries(startParams)) {
    if (!connection.startParams.includes(name)) throw new Error(`Start parameter '${named(name)}' is not declared for connection '${connection.id}' on this admin surface.`);
    if (typeof value !== 'string' || value.length > MAX_START_PARAM_LENGTH) throw new Error(`Start parameter '${name}' must be a string of at most ${MAX_START_PARAM_LENGTH} characters.`);
  }
  return { ...(startParams as Record<string, string>) };
}

function checkedScopeSetIds(scopeSetIds: unknown): readonly string[] {
  const valid = Array.isArray(scopeSetIds) && scopeSetIds.length <= MAX_SCOPE_SETS && scopeSetIds.every((id) => typeof id === 'string' && SCOPE_SET_ID_PATTERN.test(id));
  if (!valid) throw new Error(`Scope sets must be at most ${MAX_SCOPE_SETS} short ids.`);
  return [...(scopeSetIds as string[])];
}

/** The begin options the host receives: only the ones the handler passed, checked and copied. */
function beginOptions(connection: AdminSurfaceConnectionDeclaration, optional: Parameters<AdminSurfaceConnections['begin']>[1] = {}) {
  return {
    ...(optional.scopeSetIds !== undefined && { scopeSetIds: checkedScopeSetIds(optional.scopeSetIds) }),
    ...(optional.startParams !== undefined && { startParams: checkedStartParams(connection, optional.startParams) }),
  };
}

const SAFE_CODE_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const MAX_SAFE_CODE_LENGTH = 64;
const isSafeCode = (value: unknown): value is string => typeof value === 'string' && value.length <= MAX_SAFE_CODE_LENGTH && SAFE_CODE_PATTERN.test(value);

/** Only `code` and `nextAction`, and only when both are safe codes: a host that forwarded provider
 * text (an error description) by mistake must not put it in front of the person or the plugin. */
function toSignInAttempt(attempt: unknown): AdminSurfaceSignInAttempt | null {
  if (typeof attempt !== 'object' || attempt === null) return null;
  const { code, nextAction } = attempt as Readonly<Record<string, unknown>>;
  return isSafeCode(code) && isSafeCode(nextAction) ? { code, nextAction } : null;
}

/** The status shape the port promises, whatever else the host's object carried. */
function toStatus(connectionId: string, status: AdminSurfaceConnectionStatus): AdminSurfaceConnectionStatus {
  return {
    connectionId, status: status.status, accountLabel: status.accountLabel ?? null,
    grantedScopeSetIds: [...status.grantedScopeSetIds], pendingSwitchAccountLabel: status.pendingSwitchAccountLabel ?? null,
    lastSignInAttempt: toSignInAttempt(status.lastSignInAttempt),
  };
}

/** Only this connection's declared callback fields, as strings; anything else the host returned is dropped. */
function declaredCallbackFields(connection: AdminSurfaceConnectionDeclaration, fields: Readonly<Record<string, string>> | null): Readonly<Record<string, string>> | null {
  if (fields === null) return null;
  return Object.fromEntries(connection.callbackFields.filter((name) => typeof fields[name] === 'string').map((name) => [name, fields[name]!]));
}

type ConnectionsInput = { readonly gate: AgentPluginCapabilityGate; readonly host: AdminSurfaceConnections; readonly declared: readonly AdminSurfaceConnectionDeclaration[]; readonly actorId: string | undefined };

/** Account actions run for a person; a call without one (a background route) is refused. */
function requireActor(actorId: string | undefined): void {
  if (actorId === undefined) throw new Error('Account actions need a signed-in admin. Open the surface from an authenticated admin page and retry.');
}

/**
 * A token is handed out (to a handler, and through bootstrap data to the frame) only for a signed-in
 * admin: a route without one must not mint a bearer token a frame keeps until it expires. Disabling
 * the plugin cannot recall a token already handed out; disconnecting revokes it at the provider.
 */
function requireTokenActor(actorId: string | undefined): void {
  if (actorId === undefined) throw new Error('Connection access needs a signed-in admin. Open the surface from an authenticated admin page and retry.');
}

/** The read side: a token (noted for the scans) and token-free status. */
function readConnections({ gate, host, declared, actorId }: ConnectionsInput): Pick<AdminSurfaceConnections, 'getAccessToken' | 'status' | 'takeCallbackFields'> {
  return {
    getAccessToken: gate.guard(async ({ connectionId }) => {
      const { id } = declaredConnection(declared, connectionId);
      requireTokenActor(actorId);
      return gate.noteToken({ token: await host.getAccessToken({ connectionId: id }) });
    }),
    status: gate.guard(async ({ connectionId }) => {
      const { id } = declaredConnection(declared, connectionId);
      return toStatus(id, await host.status({ connectionId: id }));
    }),
    takeCallbackFields: gate.guard(async ({ connectionId, attemptId }) => {
      const connection = declaredConnection(declared, connectionId);
      if (typeof attemptId !== 'string' || !ATTEMPT_ID_PATTERN.test(attemptId)) throw new Error('The sign-in attempt id is not valid; start the sign-in again.');
      return declaredCallbackFields(connection, await host.takeCallbackFields({ connectionId: connection.id, attemptId }));
    }),
  };
}

/** The account actions: declared connection, declared start parameters, a signed-in admin. */
function actConnections({ gate, host, declared, actorId }: ConnectionsInput): Omit<AdminSurfaceConnections, 'getAccessToken' | 'status' | 'takeCallbackFields'> {
  const forActor = (connectionId: string) => { requireActor(actorId); return declaredConnection(declared, connectionId); };
  const statusAction = (run: AdminSurfaceConnections['confirmSwitch']) => gate.guard(async ({ connectionId }: { readonly connectionId: string }) => {
    const { id } = forActor(connectionId);
    return toStatus(id, await run({ connectionId: id }));
  });
  return {
    begin: gate.guard(async ({ connectionId, action }, optional) => {
      const connection = forActor(connectionId);
      if (!ACTIONS.includes(action)) throw new Error(`Account action '${named(action)}' is not one of ${ACTIONS.join(', ')}.`);
      const started = await host.begin({ connectionId: connection.id, action }, beginOptions(connection, optional));
      return { authorizationUrl: started.authorizationUrl, attemptId: started.attemptId, expiresAt: started.expiresAt };
    }),
    confirmSwitch: statusAction((input) => host.confirmSwitch(input)),
    cancelSwitch: statusAction((input) => host.cancelSwitch(input)),
    disconnect: gate.guard(async ({ connectionId }) => {
      const { id } = forActor(connectionId);
      const outcome = await host.disconnect({ connectionId: id });
      return { ...toStatus(id, outcome), revocation: outcome.revocation };
    }),
  };
}

function guardState(gate: AgentPluginCapabilityGate, host: AdminSurfaceState): AdminSurfaceState {
  return Object.freeze({
    ...guardStateReader({ gate, state: host }),
    set: gate.guard(async ({ key, value }: { readonly key: string; readonly value: AdminSurfaceStateValue }) => host.set({ key: checkedStateKey({ key }), value: storedStateValue({ gate, value }) })),
    delete: gate.guard(({ key }: { readonly key: string }) => host.delete({ key: checkedStateKey({ key }) })),
  });
}

function guardPublicConfig(gate: AgentPluginCapabilityGate, host: AdminSurfacePublicConfig, declared: readonly string[]): AdminSurfacePublicConfig {
  return Object.freeze({
    get: gate.guard(async ({ name }: { readonly name: string }) => {
      if (!declared.includes(name)) throw new Error(`This admin surface does not declare public config '${named(name)}'. Declare it in the surface's publicConfig.`);
      return host.get({ name });
    }),
  });
}

/** Read-only discovery shares revocation and actor checks with other surface-only ports. Unknown
 * host fields never reach a handler; collection and string caps bound the disclosure.
 * @complexity O(min(f, 200)) time/space for f host forms, one workspace read. */
function guardForms(required: { readonly gate: AgentPluginCapabilityGate; readonly host: AdminSurfaceForms }, optional: { readonly actorId?: string } = {}): AdminSurfaceForms {
  const { gate, host } = required;
  return Object.freeze({
    list: gate.guard(async (_input: Record<string, never>, _options: Record<string, never> = {}) => {
      requireActor(optional.actorId);
      const forms = await host.list({});
      return forms.slice(0, 200).map(({ slug, title }) => {
        if (typeof slug !== 'string' || slug.length === 0 || slug.length > 64 || typeof title !== 'string') throw new Error('The forms host returned an invalid form choice.');
        return { slug, title: title.slice(0, 1024) };
      });
    }),
  });
}

/**
 * Opens the capability session for one admin-surface handler call.
 * @param required.capabilities - The host's ports for this call (already scoped to plugin, workspace, principal).
 * @param required.isLive - False once the plugin's surface handlers are revoked.
 * @param required.declared - The surface's own capability declarations (the allowlists).
 * @param required.issued - The plugin's token memory, shared by all its calls (tools included).
 * @param optional.actorId - The signed-in admin; account actions are refused without one.
 * @returns Wrapped capabilities plus the shared `release` (result) and `sanitize` (error) gates.
 * @complexity O(1) to open; each check is bounded by the declared lists and the value caps.
 */
export function openAdminSurfaceCapabilitySession(
  required: {
    readonly capabilities: AdminSurfaceCapabilities; readonly isLive: () => boolean; readonly declared: AdminSurfaceCapabilityDeclarations;
    readonly issued: IssuedTokenMemory;
  },
  optional: { readonly actorId?: string } = {},
) {
  const { capabilities: host, isLive, declared, issued } = required;
  const gate = openCapabilityGate({ isLive, issued });
  const input: ConnectionsInput = { gate, host: host.connections, declared: declared.connections ?? [], actorId: optional.actorId };
  const { deliveryAdapters } = declared;
  const deliveryBindings = deliveryAdapters === undefined || host.deliveryBindings === undefined ? undefined
    : guardDeliveryBindings({ gate, host: host.deliveryBindings, adapterIds: deliveryAdapters, connectionIds: input.declared.map((connection) => connection.id) }, { actorId: optional.actorId });
  const capabilities: AdminSurfaceCapabilities = Object.freeze({
    ...guardSharedCapabilities({ gate, host }),
    connections: Object.freeze({ ...readConnections(input), ...actConnections(input) }),
    state: guardState(gate, host.state),
    publicConfig: guardPublicConfig(gate, host.publicConfig, declared.publicConfig ?? []),
    ...(deliveryBindings && { deliveryBindings }),
    ...(declared.forms?.includes('list') && host.forms !== undefined && { forms: guardForms({ gate, host: host.forms }, optional) }),
  });
  return { capabilities, release: gate.release, sanitize: gate.sanitize };
}

src/admin-surfaces/surface-handlers.ts.source:
/**
 * @file Plugin-supplied server-side handlers for admin surfaces: a surface may name a contained
 * `.mjs` `handlerModule` that answers its declared actions and may provide its bootstrap data.
 *
 * Why it exists: without it a host can only answer a surface's actions with its own code, so a
 * provider plugin cannot ship a working settings or resource-chooser screen. Why it is safe to run plugin code
 * here: the module loads only through the lifecycle's one executable loader
 * (`defineExecutablePluginContribution`: active plugin, shipped digest, on-disk containment), it
 * receives host capability ports (never a raw secret) through the admin-surface capability session
 * (`./surface-capabilities.ts`: only the surface's declared connections and config, revoked on disable,
 * results and errors scanned for tokens the call obtained, the same gate as executable tools), and the
 * dispatcher still checks the declared input and result schemas around it.
 * Bootstrap data is the one answer allowed to carry an access token (a surface may need a short-lived
 * one); it must match the surface's declared `bootstrap` schema and is never cached by the host.
 */
import { defineExecutablePluginContribution, type LoadedPluginContribution, type PluginContributionDefinition } from '../lifecycle/contribution-loader.js';
import type { IssuedTokenMemories, IssuedTokenMemory } from '../lifecycle/tools/capabilities.js';
import { openAdminSurfaceCapabilitySession, type AdminSurfaceCapabilities, type AdminSurfaceCapabilitiesPort } from './surface-capabilities.js';
import { AdminSurfaceActionError, type AdminSurfaceActionHandler } from './action-dispatcher.js';
import { validateAdminSurfaceActionValue, type AdminSurfaceActionSchema } from './action-schema.js';
import { parseAdminSurfacesFile, type AdminSurfaceDescriptor } from './descriptor.js';

/** Who a call is for. The host route establishes it; plugin and surface ids are rebound to the
 * loaded module's own before a handler sees them. */
export interface AdminSurfaceHandlerContext {
  readonly workspaceId: string;
  readonly principalId?: string;
  readonly pluginId: string;
  readonly surfaceId: string;
}

/** Which kind of host is running the surface, so a plugin picks its flow (for example a sign-in in
 * the system browser on desktop) without inferring it from config. */
export type AdminSurfaceHostKind = 'hosted' | 'desktop';
const HOST_KINDS: readonly string[] = ['hosted', 'desktop'] satisfies readonly AdminSurfaceHostKind[];

/** The context a handler sees: the route's context plus the plugin's own declared connection ids
 * (ids, never refs: the host resolves the ref, so a plugin can never name another plugin's connection)
 * and the host kind the host was built with (never a caller's or the plugin's value). */
export interface AdminSurfacePluginContext extends AdminSurfaceHandlerContext {
  readonly connectionIds: readonly string[];
  readonly hostKind: AdminSurfaceHostKind;
}

/** What a bootstrap provider receives. */
export interface AdminSurfaceBootstrapCall {
  readonly capabilities: AdminSurfaceCapabilities;
  readonly context: AdminSurfacePluginContext;
}

/** What an action handler receives. `input` already matched the action's declared input schema. */
export interface AdminSurfaceHandlerCall extends AdminSurfaceBootstrapCall {
  readonly input: unknown;
  /** Builds a surface-safe failure to throw: `code` (lowercase hyphenated) and `message` reach the frame. */
  readonly fail: (required: { readonly code: string; readonly message: string }, optional?: { readonly retryable?: boolean }) => Error;
}

/** What a handler module's default export must be. */
export interface AdminSurfaceHandlerModule {
  /** Keyed by declared action name; a declared action without one answers `action-unavailable`. */
  readonly actions: Readonly<Record<string, (required: AdminSurfaceHandlerCall, optional?: Record<string, never>) => unknown>>;
  /** Data the surface starts with; requires a `bootstrap` schema on the surface. */
  readonly bootstrap?: (required: AdminSurfaceBootstrapCall, optional?: Record<string, never>) => unknown;
}

type HandledSurface = AdminSurfaceDescriptor & { readonly handlerModule: string };
export type LoadedAdminSurfaceHandlers = LoadedPluginContribution<HandledSurface, AdminSurfaceHandlerModule>;

export const ADMIN_SURFACE_PLUGIN_DISABLED_MESSAGE = 'This plugin was disabled, so its admin surface cannot act. Re-enable the plugin and reopen the surface.';
const FAILURE_CODE_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const MAX_FAILURE_CODE_LENGTH = 64;
const MAX_FAILURE_MESSAGE_LENGTH = 300;

const isFunction = (value: unknown) => typeof value === 'function';
const isRecord = (value: unknown): value is Readonly<Record<string, unknown>> => typeof value === 'object' && value !== null && !Array.isArray(value);

/** The module's export as a handler module, or why not. Shape only; declarations are checked at sync. @complexity O(a) exported actions. */
function validateHandlerModule({ exported }: { readonly exported: unknown }): AdminSurfaceHandlerModule | string {
  if (!isRecord(exported)) return "its module's default export is not an object";
  if (!isRecord(exported.actions) || !Object.values(exported.actions).every(isFunction)) return "its module's default export needs an actions object of functions";
  if (exported.bootstrap !== undefined && !isFunction(exported.bootstrap)) return 'bootstrap must be a function';
  return exported as unknown as AdminSurfaceHandlerModule;
}

/**
 * The executable contribution for the host's surfaces file (the same file `defineAdminSurfaceContribution`
 * reads): one item per surface that names a `handlerModule`.
 * @param required.filename - The host-named surfaces file at the plugin root.
 * @complexity O(1); each load parses the file and performs one contained import per handled surface.
 */
export function defineAdminSurfaceHandlerContribution(
  required: { readonly filename: string },
  _optional: Record<string, never> = {},
): PluginContributionDefinition<HandledSurface, LoadedAdminSurfaceHandlers> {
  return defineExecutablePluginContribution<HandledSurface, AdminSurfaceHandlerModule>({
    filename: required.filename, contribution: 'admin surface handlers',
    parse: ({ raw }) => {
      const parsed = parseAdminSurfacesFile({ raw });
      return parsed.ok ? { ok: true, descriptors: parsed.descriptors.filter((descriptor): descriptor is HandledSurface => descriptor.handlerModule !== undefined) } : parsed;
    },
    modulePath: ({ descriptor }) => descriptor.handlerModule, validate: validateHandlerModule,
    refusal: ({ plugin, descriptor, reason }) => `admin surface handlers for '${descriptor.id}' from '${plugin.pluginId}' were not loaded: ${reason}`,
  });
}

/** A surface-safe failure, or a generic one when the plugin's code is not a valid id. @complexity O(1). */
function fail(required: { readonly code: string; readonly message: string }, optional: { readonly retryable?: boolean } = {}): Error {
  const { code, message } = required;
  if (typeof code !== 'string' || code.length > MAX_FAILURE_CODE_LENGTH || !FAILURE_CODE_PATTERN.test(code)) return new Error('a plugin failure used an invalid code');
  return new AdminSurfaceActionError({ code, message: String(message).slice(0, MAX_FAILURE_MESSAGE_LENGTH) }, { retryable: optional.retryable === true });
}

/** Why a loaded module cannot answer for its surface, or null. @complexity O(a) exported actions. */
function admissionRefusal({ descriptor, module }: LoadedAdminSurfaceHandlers): string | null {
  const undeclared = Object.keys(module.actions).find((name) => !descriptor.actions.some((action) => action.name === name));
  if (undeclared !== undefined) return `it exports a handler for undeclared action '${undeclared.slice(0, 64)}'`;
  return module.bootstrap !== undefined && descriptor.bootstrap === undefined ? 'it exports bootstrap() but the surface declares no bootstrap schema' : null;
}

interface AdmittedSurface {
  readonly loaded: LoadedAdminSurfaceHandlers;
  readonly handlers: Readonly<Record<string, AdminSurfaceActionHandler<AdminSurfaceHandlerContext>>>;
  readonly isLive: () => boolean;
  /** Tokens the plugin's calls obtained (tools included); module state can carry one from call to call. */
  readonly issued: IssuedTokenMemory;
}

/** Plugin and surface ids cannot contain NUL, so the key is unambiguous. */
const keyOf = (pluginId: string, surfaceId: string) => `${pluginId}\u0000${surfaceId}`;

/**
 * Holds the admitted handler modules and answers for them. Call `sync` with every load of
 * `defineAdminSurfaceHandlerContribution` (on boot and on every activation change); a surface missing
 * from a load loses its handlers, and capabilities its module kept are revoked.
 * @param required.capabilities - Host port building one call's admin-surface capabilities.
 * @param required.issuedTokens - Per-plugin token memory shared with the plugin's tool projection.
 * @param required.hostKind - The kind of host this process is; every handler and bootstrap call sees it.
 * @throws TypeError when `hostKind` is neither `hosted` nor `desktop`.
 * @returns `sync`, plus `handlersFor` and `bootstrapData` for the host's action dispatcher and bootstrap route.
 * @complexity sync is O(s + a) surfaces and actions; lookups are O(1).
 */
export function createAdminSurfaceHandlerHost(required: { readonly capabilities: AdminSurfaceCapabilitiesPort; readonly issuedTokens: IssuedTokenMemories; readonly hostKind: AdminSurfaceHostKind }, _optional: Record<string, never> = {}) {
  // Checked at run time too: a JavaScript host may pass an unchecked config value, and a plugin would pick its flow from it.
  if (!HOST_KINDS.includes(required.hostKind)) throw new TypeError("createAdminSurfaceHandlerHost: hostKind must be 'hosted' or 'desktop'.");
  const { hostKind } = required;
  let admitted = new Map<string, AdmittedSurface>();

  /** One call's capability session, scoped to the loaded plugin and the route's workspace/principal. */
  function sessionFor(self: AdmittedSurface, context: AdminSurfaceHandlerContext): { session: ReturnType<typeof openAdminSurfaceCapabilitySession>; context: AdminSurfacePluginContext } {
    const { pluginId, descriptor } = self.loaded;
    const principal = context.principalId === undefined ? {} : { principalId: context.principalId };
    const capabilities = required.capabilities({ pluginId, workspaceId: context.workspaceId, ...principal });
    const session = openAdminSurfaceCapabilitySession({ capabilities, isLive: self.isLive, declared: descriptor, issued: self.issued }, { ...(principal.principalId !== undefined && { actorId: principal.principalId }) });
    const connectionIds = (descriptor.connections ?? []).map((connection) => connection.id);
    return { session, context: { workspaceId: context.workspaceId, ...principal, pluginId, surfaceId: descriptor.id, connectionIds, hostKind } };
  }

  function actionHandler(self: AdmittedSurface, run: AdminSurfaceHandlerModule['actions'][string]): AdminSurfaceActionHandler<AdminSurfaceHandlerContext> {
    return async ({ payload, context: caller }) => {
      if (!self.isLive()) throw new AdminSurfaceActionError({ code: 'plugin-disabled', message: ADMIN_SURFACE_PLUGIN_DISABLED_MESSAGE });
      const { session, context } = sessionFor(self, caller);
      try { return session.release({ value: await run({ input: payload, capabilities: session.capabilities, context, fail }) }); }
      catch (error) { throw session.sanitize({ error }); }
    };
  }

  /** A generation for one surface; live only while `admitted` holds this exact object. */
  function admit(key: string, loaded: LoadedAdminSurfaceHandlers): AdmittedSurface {
    const declared = loaded.descriptor.actions.filter((action) => Object.hasOwn(loaded.module.actions, action.name));
    const self: AdmittedSurface = { loaded, handlers: {}, isLive: () => admitted.get(key) === self, issued: required.issuedTokens.forPlugin({ pluginId: loaded.pluginId }) };
    Object.assign(self.handlers, Object.fromEntries(declared.map((action) => [action.name, actionHandler(self, loaded.module.actions[action.name]!)])));
    return Object.freeze(self);
  }

  /** The previous generation when module and declaration are unchanged, so re-syncing never revokes it. */
  function unchanged(previous: AdmittedSurface | undefined, loaded: LoadedAdminSurfaceHandlers): AdmittedSurface | undefined {
    const same = previous !== undefined && previous.loaded.module === loaded.module && JSON.stringify(previous.loaded.descriptor) === JSON.stringify(loaded.descriptor);
    return same ? previous : undefined;
  }

  return {
    /** Admits one load result. @returns The loader's refusals plus this seam's own, in order. */
    sync(input: { readonly loaded: readonly LoadedAdminSurfaceHandlers[]; readonly refusals: readonly string[] }, _options: Record<string, never> = {}): { readonly refusals: readonly string[] } {
      const refusals = [...input.refusals];
      const claims = new Map<string, number>();
      for (const entry of input.loaded) claims.set(keyOf(entry.pluginId, entry.descriptor.id), (claims.get(keyOf(entry.pluginId, entry.descriptor.id)) ?? 0) + 1);
      const next = new Map<string, AdmittedSurface>();
      const previous = admitted;
      for (const entry of input.loaded) {
        const key = keyOf(entry.pluginId, entry.descriptor.id);
        const reason = claims.get(key)! > 1 ? 'more than one handler module claims this surface' : admissionRefusal(entry);
        const line = `admin surface handlers for '${entry.descriptor.id}' from '${entry.pluginId}' were not loaded: ${reason}`;
        if (reason !== null) { if (!refusals.includes(line)) refusals.push(line); continue; }
        next.set(key, unchanged(previous.get(key), entry) ?? admit(key, entry));
      }
      admitted = next;
      return { refusals };
    },
    /** The plugin's handlers for one surface (empty when none are admitted), for `createAdminSurfaceActionDispatcher`. */
    handlersFor(input: { readonly pluginId: string; readonly surfaceId: string }, _options: Record<string, never> = {}): Readonly<Record<string, AdminSurfaceActionHandler<AdminSurfaceHandlerContext>>> {
      return admitted.get(keyOf(input.pluginId, input.surfaceId))?.handlers ?? {};
    },
    /** The plugin's bootstrap data for `context`'s surface, or null when it provides none.
     * @throws Error when the data does not match the declared schema (the message names a path, never a value). */
    async bootstrapData(input: { readonly context: AdminSurfaceHandlerContext }, _options: Record<string, never> = {}): Promise<unknown> {
      const self = admitted.get(keyOf(input.context.pluginId, input.context.surfaceId));
      const provide = self?.loaded.module.bootstrap;
      if (self === undefined || provide === undefined) return null;
      const { session, context } = sessionFor(self, input.context);
      let data: unknown;
      try { data = await provide({ capabilities: session.capabilities, context }); } catch (error) { throw session.sanitize({ error }); }
      // Admission guarantees a schema whenever the module provides bootstrap data.
      const violation = validateAdminSurfaceActionValue({ schema: self.loaded.descriptor.bootstrap as AdminSurfaceActionSchema, value: data });
      if (violation !== null) throw new Error(`Admin surface '${context.surfaceId}' from '${context.pluginId}' returned bootstrap data outside its declared schema (${violation}); report it to the plugin author.`);
      return data;
    },
  };
}

src/admin-surfaces/action-schema.ts.source:
/**
 * @file A deliberately small, closed subset of JSON Schema for admin-surface action inputs and
 * results: checked once when the descriptor is parsed, then used to validate every payload.
 *
 * Why not full JSON Schema: a surface's payload crosses a trust boundary (plugin UI -> host
 * handler), so the schema language is fail-closed. An unknown keyword refuses the descriptor
 * instead of being ignored (a plugin cannot rely on `pattern` or `format` that would silently pass),
 * objects are closed (no undeclared keys reach a handler), and every node must name its `type`.
 * Violation messages name the path only, never the value, so a rejected payload cannot echo a secret.
 */

export type AdminSurfaceActionSchema =
  | { readonly type: 'object'; readonly properties?: Readonly<Record<string, AdminSurfaceActionSchema>>; readonly required?: readonly string[]; readonly additionalProperties?: false }
  | { readonly type: 'array'; readonly items: AdminSurfaceActionSchema; readonly maxItems?: number }
  | { readonly type: 'string'; readonly minLength?: number; readonly maxLength?: number; readonly enum?: readonly string[] }
  | { readonly type: 'number' | 'integer'; readonly minimum?: number; readonly maximum?: number }
  | { readonly type: 'boolean' | 'null' };

type SchemaNode = Readonly<Record<string, unknown>>;

const MAX_DEPTH = 8;
/** Applies when an array schema declares no `maxItems`, so no payload is unbounded. */
const DEFAULT_MAX_ITEMS = 1000;
const ANNOTATIONS = ['type', 'title', 'description'];
const KEYWORDS: Readonly<Record<string, readonly string[]>> = {
  object: ['properties', 'required', 'additionalProperties'],
  array: ['items', 'maxItems'],
  string: ['minLength', 'maxLength', 'enum'],
  number: ['minimum', 'maximum'],
  integer: ['minimum', 'maximum'],
  boolean: [],
  null: [],
};

function isPlainObject(value: unknown): value is SchemaNode {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const proto: unknown = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}
const isCount = (value: unknown) => value === undefined || (Number.isInteger(value) && (value as number) >= 0);
const isBound = (value: unknown) => value === undefined || (typeof value === 'number' && Number.isFinite(value));

/**
 * Why a declared schema is unusable, or `null` when it is a valid member of the subset.
 * @complexity O(n) schema nodes; recursion bounded by {@link MAX_DEPTH}.
 */
export function checkAdminSurfaceActionSchema(required: { readonly schema: unknown }, optional: { readonly depth?: number } = {}): string | null {
  const { schema } = required;
  const depth = optional.depth ?? 0;
  if (!isPlainObject(schema)) return 'must be an object';
  if (depth > MAX_DEPTH) return `nests deeper than ${MAX_DEPTH} levels`;
  const type = schema.type;
  if (typeof type !== 'string' || !Object.hasOwn(KEYWORDS, type)) return 'must declare a supported type';
  const unknown = Object.keys(schema).find((key) => !ANNOTATIONS.includes(key) && !KEYWORDS[type]!.includes(key));
  if (unknown !== undefined) return `uses unsupported keyword '${unknown}'`;
  return checkKeywords(schema, type, depth);
}

/** @complexity O(n) child schema nodes. */
function checkKeywords(schema: SchemaNode, type: string, depth: number): string | null {
  if (type === 'object') return checkObject(schema, depth);
  if (type === 'array') return checkArray(schema, depth);
  if (type === 'string') return checkString(schema);
  if (type === 'number' || type === 'integer') return isBound(schema.minimum) && isBound(schema.maximum) ? null : 'minimum/maximum must be finite numbers';
  return null;
}

function checkObject(schema: SchemaNode, depth: number): string | null {
  const properties = schema.properties ?? {};
  if (!isPlainObject(properties)) return 'properties must be an object';
  if (schema.additionalProperties !== undefined && schema.additionalProperties !== false) return 'additionalProperties may only be false (objects are closed)';
  if (!listsDeclaredKeys(schema.required ?? [], properties)) return 'required must list declared properties';
  for (const [key, child] of Object.entries(properties)) {
    const reason = checkAdminSurfaceActionSchema({ schema: child }, { depth: depth + 1 });
    if (reason !== null) return `property '${key}' ${reason}`;
  }
  return null;
}

const listsDeclaredKeys = (required: unknown, properties: SchemaNode) => Array.isArray(required) && required.every((key) => typeof key === 'string' && Object.hasOwn(properties, key));

function checkArray(schema: SchemaNode, depth: number): string | null {
  if (!isCount(schema.maxItems)) return 'maxItems must be a non-negative integer';
  const reason = checkAdminSurfaceActionSchema({ schema: schema.items }, { depth: depth + 1 });
  return reason === null ? null : `items ${reason}`;
}

function checkString(schema: SchemaNode): string | null {
  if (!isCount(schema.minLength) || !isCount(schema.maxLength)) return 'minLength/maxLength must be non-negative integers';
  const values = schema.enum;
  if (values === undefined) return null;
  return Array.isArray(values) && values.length > 0 && values.every((value) => typeof value === 'string') ? null : 'enum must be a non-empty list of strings';
}

/**
 * The first place `value` violates a schema that passed {@link checkAdminSurfaceActionSchema}, or
 * `null` when it conforms. The message names a path such as `$.rows[2]`, never the offending value.
 * @complexity O(v) values visited.
 */
export function validateAdminSurfaceActionValue(required: { readonly schema: AdminSurfaceActionSchema; readonly value: unknown }, optional: { readonly path?: string } = {}): string | null {
  const validate = VALIDATORS[required.schema.type] as (schema: AdminSurfaceActionSchema, value: unknown, path: string) => string | null;
  return validate(required.schema, required.value, optional.path ?? '$');
}

function validateObject(schema: Extract<AdminSurfaceActionSchema, { type: 'object' }>, value: unknown, path: string): string | null {
  if (!isPlainObject(value)) return `${path} must be an object`;
  const properties = schema.properties ?? {};
  const extra = Object.keys(value).find((key) => !Object.hasOwn(properties, key));
  if (extra !== undefined) return `${path} has an undeclared property ${JSON.stringify(extra.slice(0, 64))}`;
  const missing = (schema.required ?? []).find((key) => !Object.hasOwn(value, key));
  if (missing !== undefined) return `${path}.${missing} is required`;
  for (const [key, child] of Object.entries(value)) {
    const reason = validateAdminSurfaceActionValue({ schema: properties[key]!, value: child }, { path: `${path}.${key}` });
    if (reason !== null) return reason;
  }
  return null;
}

function validateArray(schema: Extract<AdminSurfaceActionSchema, { type: 'array' }>, value: unknown, path: string): string | null {
  if (!Array.isArray(value)) return `${path} must be an array`;
  if (value.length > (schema.maxItems ?? DEFAULT_MAX_ITEMS)) return `${path} has too many items`;
  for (const [index, item] of value.entries()) {
    const reason = validateAdminSurfaceActionValue({ schema: schema.items, value: item }, { path: `${path}[${index}]` });
    if (reason !== null) return reason;
  }
  return null;
}

function validateString(schema: Extract<AdminSurfaceActionSchema, { type: 'string' }>, value: unknown, path: string): string | null {
  if (typeof value !== 'string') return `${path} must be a string`;
  if (value.length < (schema.minLength ?? 0) || value.length > (schema.maxLength ?? Infinity)) return `${path} has the wrong length`;
  return schema.enum === undefined || schema.enum.includes(value) ? null : `${path} is not one of the allowed values`;
}

function validateNumber(schema: Extract<AdminSurfaceActionSchema, { type: 'number' | 'integer' }>, value: unknown, path: string): string | null {
  const ok = typeof value === 'number' && Number.isFinite(value) && (schema.type === 'number' || Number.isInteger(value));
  if (!ok) return `${path} must be ${schema.type === 'integer' ? 'an integer' : 'a number'}`;
  return inRange(value, schema.minimum, schema.maximum) ? null : `${path} is out of range`;
}

const inRange = (value: number, minimum: number | undefined, maximum: number | undefined) => value >= (minimum ?? -Infinity) && value <= (maximum ?? Infinity);

/** One validator per declared `type`; the schema was checked at parse time, so the lookup always hits. */
const VALIDATORS: { readonly [T in AdminSurfaceActionSchema['type']]: (schema: Extract<AdminSurfaceActionSchema, { type: T }>, value: unknown, path: string) => string | null } = {
  object: validateObject,
  array: validateArray,
  string: validateString,
  number: validateNumber,
  integer: validateNumber,
  boolean: (_schema, value, path) => (typeof value === 'boolean' ? null : `${path} must be a boolean`),
  null: (_schema, value, path) => (value === null ? null : `${path} must be null`),
};

/** One request-size cap for the browser-side host check and the server-side dispatcher (the
 * authoritative one: string schemas carry no default maxLength). */
const MAX_PAYLOAD_CHARS = 64 * 1024;

/** True when `payload` serializes to more than 64 KiB of JSON text, or cannot be serialized. @complexity O(payload size). */
export function exceedsAdminSurfacePayloadLimit(required: { readonly payload: unknown }, _optional: Record<string, never> = {}): boolean {
  try { return (JSON.stringify(required.payload)?.length ?? Infinity) > MAX_PAYLOAD_CHARS; } catch { return true; }
}

src/admin-surfaces/contribution.ts.source:
/**
 * @file Plugs admin surfaces into the existing plugin contribution loader
 * (`../lifecycle/contribution-loader.ts`) and serves their declared files.
 *
 * Why the filename is a parameter: the host names its own contribution file (one host might use
 * `<product>-admin-surfaces.json`), exactly as it does for every other seam; Jini never hardcodes a
 * product prefix. Surfaces are a DATA contribution: nothing is imported into the server process. The
 * loader still applies the shared trust gate (active + shipped digest), and file reads go through
 * the lifecycle's `readTrustedPluginFile`, which resolves symlinks and refuses anything outside the
 * package root.
 */
import type { PluginContributionDefinition } from '../lifecycle/contribution-loader.js';
import type { TrustedPluginPackage } from '../lifecycle/trusted-plugin-files.js';
import { parseAdminSurfacesFile, type AdminSurfaceDescriptor } from './descriptor.js';
import { adminSurfaceFileHeaders } from './sandbox.js';

/** One surface the trust gate admitted, with the package its files are read from. */
export interface LoadedAdminSurface {
  readonly plugin: TrustedPluginPackage;
  readonly descriptor: AdminSurfaceDescriptor;
}

/**
 * The contribution definition for a host-chosen filename. Pass it to the lifecycle's
 * `loadPluginContributions({ workspaceId, definition })`.
 * @complexity O(1) composition; parsing is O(file size).
 */
export function defineAdminSurfaceContribution(required: { readonly filename: string }, _optional: Record<string, never> = {}): PluginContributionDefinition<AdminSurfaceDescriptor, LoadedAdminSurface> {
  return {
    filename: required.filename,
    contribution: 'admin surfaces',
    kind: 'data',
    parse: ({ raw }) => parseAdminSurfacesFile({ raw }),
    load: ({ plugin, descriptor }) => ({ plugin, descriptor }),
  };
}

/**
 * Reads one file of a loaded surface for serving, with the headers it must be served with. Only the
 * entry and the declared `files` are ever read; any other path answers `not-declared` without I/O.
 * @param required.readFile - The lifecycle's `readTrustedPluginFile` (on-disk containment check).
 * @complexity O(f) declared files plus the read.
 */
export async function readAdminSurfaceFile(required: {
  readonly surface: LoadedAdminSurface;
  readonly path: string;
  readonly readFile: (input: { readonly plugin: TrustedPluginPackage; readonly filename: string }) => Promise<string>;
}, _optional: Record<string, never> = {}): Promise<{ readonly ok: true; readonly body: string; readonly headers: Readonly<Record<string, string>> } | { readonly ok: false; readonly reason: 'not-declared' }> {
  const { surface, path } = required;
  if (path !== surface.descriptor.entry && !surface.descriptor.files.includes(path)) return { ok: false, reason: 'not-declared' };
  const body = await required.readFile({ plugin: surface.plugin, filename: path });
  return { ok: true, body, headers: adminSurfaceFileHeaders({ descriptor: surface.descriptor, path }) };
}

src/admin-surfaces/external-links.ts.source:
/**
 * @file Host-mediated external links: a surface declares the https origins it may link to
 * (`linkOrigins`, parsed in `./descriptor.ts`), and asks the host page to open a URL with an `open-link` message; the host page
 * passes that message to `openAdminSurfaceLink`, which opens it through the host's own opener only
 * when it comes from this mount and names a declared https origin.
 *
 * Why the host opens links: a surface frame is sandboxed without `allow-popups` or top navigation,
 * so it cannot open anything itself, and must not: the host decides HOW (a new tab with `noopener`
 * on the web, the system browser on desktop). Why the gate is this strict: a link the host opens
 * leaves the sandbox entirely, so the destination is limited to what the shipped, digest-checked
 * surfaces file declared, and the opener receives the URL parser's normalized form so it never
 * re-parses a string this gate judged differently.
 */
import { frameTransportRefusal, REQUEST_ID_PATTERN, type AdminSurfaceMessageEvent, type AdminSurfaceMountRecord } from './host-validator.js';
import {
  ADMIN_SURFACE_PROTOCOL, ADMIN_SURFACE_PROTOCOL_VERSION, adminSurfaceActionResponse,
  type AdminSurfaceActionResponse, type AdminSurfaceOpenLinkRequest,
} from './protocol.js';

/** Longer URLs are refused, not cut: a truncated link would open somewhere the plugin did not mean. */
const MAX_LINK_URL_LENGTH = 2048;

/** Host port: opens an already-checked https URL however the host decides (new tab with `noopener`, system browser). */
export type AdminSurfaceOpenLinkPort = (required: { readonly url: string }, optional?: Record<string, never>) => void | Promise<void>;

/** `ignored`: not this mount's open-link message; drop silently. Otherwise post `response` back to the frame. */
export type AdminSurfaceLinkVerdict =
  | { readonly ok: true; readonly url: string; readonly response: AdminSurfaceActionResponse }
  | { readonly ok: false; readonly ignored: string }
  | { readonly ok: false; readonly refused: string; readonly response: AdminSurfaceActionResponse };

function isOpenLinkEnvelope(data: unknown): data is AdminSurfaceOpenLinkRequest {
  if (typeof data !== 'object' || data === null) return false;
  const message = data as Readonly<Record<string, unknown>>;
  const isProtocol = message.protocol === ADMIN_SURFACE_PROTOCOL && message.version === ADMIN_SURFACE_PROTOCOL_VERSION && message.kind === 'open-link';
  return isProtocol && typeof message.mountId === 'string' && typeof message.requestId === 'string' && REQUEST_ID_PATTERN.test(message.requestId) && typeof message.url === 'string';
}

type LinkRefusal = { readonly code: string; readonly message: string };

/** The normalized URL when `raw` may be opened, or why not. Messages never echo the URL. @complexity O(n) in the URL length. */
function checkLink(raw: string, origins: readonly string[]): { readonly url: string } | LinkRefusal {
  if (raw.length > MAX_LINK_URL_LENGTH) return { code: 'link-too-long', message: 'The link is too long.' };
  if (!URL.canParse(raw)) return { code: 'link-invalid', message: 'That link is not a valid web address.' };
  const parsed = new URL(raw);
  if (parsed.protocol !== 'https:') return { code: 'link-not-https', message: 'Only https links can be opened.' };
  // Credentials in a link are a phishing shape (`https://trusted@elsewhere`) and never needed to open a page.
  if (parsed.username !== '' || parsed.password !== '') return { code: 'link-invalid', message: 'That link is not a valid web address.' };
  if (!origins.includes(parsed.origin)) return { code: 'link-undeclared', message: 'This surface did not declare that link destination.' };
  return { url: parsed.href };
}

/**
 * Judges one `message` event as an open-link request for one mount and, when it passes, opens it
 * through the host's port. Pass every message event here as well as to `validateAdminSurfaceMessage`;
 * each ignores the other's messages.
 * @param required.openLink - The host's opener; called at most once, with the normalized URL.
 * @complexity O(n) in the URL length, plus the opener.
 */
export async function openAdminSurfaceLink(
  required: { readonly event: AdminSurfaceMessageEvent; readonly mount: AdminSurfaceMountRecord; readonly openLink: AdminSurfaceOpenLinkPort },
  _optional: Record<string, never> = {},
): Promise<AdminSurfaceLinkVerdict> {
  const { event, mount, openLink } = required;
  const transport = frameTransportRefusal({ event, mount });
  if (transport !== null) return { ok: false, ignored: transport };
  if (!isOpenLinkEnvelope(event.data)) return { ok: false, ignored: 'not-an-open-link' };
  const request = event.data;
  if (request.mountId !== mount.mountId) return { ok: false, ignored: 'mount-mismatch' };
  const refuse = (refusal: LinkRefusal, retryable = false) => ({ ok: false as const, refused: refusal.code, response: adminSurfaceActionResponse({ request, outcome: { ok: false, error: { ...refusal, retryable } } }) });
  const checked = checkLink(request.url, mount.descriptor.linkOrigins ?? []);
  if (!('url' in checked)) return refuse(checked);
  try { await openLink({ url: checked.url }); } catch { return refuse({ code: 'link-failed', message: 'The host could not open the link. Try again.' }, true); }
  return { ok: true, url: checked.url, response: adminSurfaceActionResponse({ request, outcome: { ok: true, result: null } }) };
}

src/admin-surfaces/sandbox.ts.source:
/**
 * @file The isolation contract a host applies when it renders and serves an admin surface: the
 * iframe attributes, the Content-Security-Policy and headers for each served surface file, the mount
 * nonce, and the short-lived, never-cached bootstrap envelope.
 *
 * Why these are pure helpers instead of host code: every host must apply the SAME strict values, and
 * the values are the security boundary (no same-origin, no inline script, no direct network access
 * unless the descriptor declared and validation accepted an https origin). Hosts call these and only
 * choose routes.
 */
import type { AdminSurfaceDescriptor } from './descriptor.js';
import { ADMIN_SURFACE_SANDBOX, type AdminSurfaceBootstrap } from './protocol.js';

/** Bootstrap data is meant to live for one render: one minute, fixed so no host can lengthen it. */
const BOOTSTRAP_TTL_MS = 60_000;

const CONTENT_TYPES: Readonly<Record<string, string>> = {
  html: 'text/html; charset=utf-8',
  mjs: 'text/javascript; charset=utf-8',
  js: 'text/javascript; charset=utf-8',
  css: 'text/css; charset=utf-8',
  json: 'application/json; charset=utf-8',
};

/**
 * The attributes for the `<iframe>` that renders a surface. `sandbox` is exactly `allow-scripts`:
 * the frame gets an opaque origin, so it cannot read the host's cookies, storage or DOM.
 * @complexity O(1).
 */
export function adminSurfaceFrameAttributes(required: { readonly src: string; readonly title: string }, _optional: Record<string, never> = {}) {
  return { src: required.src, title: required.title, sandbox: ADMIN_SURFACE_SANDBOX, referrerPolicy: 'no-referrer' } as const;
}

/**
 * The CSP for every file of one surface. Starts from `default-src 'none'`; scripts, styles, images
 * and fonts may come from the surface's own files; `connect-src` and `frame-src` are closed unless the
 * descriptor declared validated https origins. The `sandbox` directive keeps the document sandboxed
 * even when opened directly rather than through the host's iframe.
 * @complexity O(c) declared CSP sources.
 */
export function adminSurfaceContentSecurityPolicy(required: { readonly descriptor: Pick<AdminSurfaceDescriptor, 'csp'> }, _optional: Record<string, never> = {}): string {
  const extra = (directive: keyof AdminSurfaceDescriptor['csp']) => required.descriptor.csp[directive] ?? [];
  const own = (directive: keyof AdminSurfaceDescriptor['csp']) => [`'self'`, ...extra(directive)].join(' ');
  const closed = (directive: keyof AdminSurfaceDescriptor['csp']) => (extra(directive).length ? extra(directive).join(' ') : `'none'`);
  return [
    `default-src 'none'`,
    `script-src ${own('script-src')}`,
    `style-src ${own('style-src')}`,
    `img-src ${own('img-src')}`,
    `font-src ${own('font-src')}`,
    `connect-src ${closed('connect-src')}`,
    `frame-src ${closed('frame-src')}`,
    `form-action 'none'`,
    `base-uri 'none'`,
    `frame-ancestors 'self'`,
    `sandbox ${ADMIN_SURFACE_SANDBOX}`,
  ].join('; ');
}

/**
 * Response headers for one served surface file. Script files carry `Access-Control-Allow-Origin: *`
 * because a module script requested by an opaque-origin document is a cross-origin CORS fetch; the
 * files are static plugin code fetched without credentials, so they must never contain secrets.
 * @complexity O(c) declared CSP sources.
 */
export function adminSurfaceFileHeaders(required: { readonly descriptor: Pick<AdminSurfaceDescriptor, 'csp'>; readonly path: string }, _optional: Record<string, never> = {}): Readonly<Record<string, string>> {
  const extension = required.path.slice(required.path.lastIndexOf('.') + 1);
  const script = extension === 'mjs' || extension === 'js';
  return {
    'Content-Type': CONTENT_TYPES[extension] ?? 'application/octet-stream',
    'Content-Security-Policy': adminSurfaceContentSecurityPolicy({ descriptor: required.descriptor }),
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'no-referrer',
    'Cache-Control': 'no-cache',
    ...(script ? { 'Access-Control-Allow-Origin': '*' } : {}),
  };
}

/** One rendered surface: the nonce its messages must echo (they must also come from origin "null").
 * @complexity O(1). */
export function createAdminSurfaceMount(
  required: { readonly surfaceId: string },
  optional: { readonly randomBytes?: (input: { readonly length: number }) => Uint8Array } = {},
) {
  const randomBytes = optional.randomBytes ?? (({ length }) => globalThis.crypto.getRandomValues(new Uint8Array(length)));
  const mountId = Array.from(randomBytes({ length: 16 }), (byte) => byte.toString(16).padStart(2, '0')).join('');
  return { surfaceId: required.surfaceId, mountId };
}

/**
 * The envelope a host server returns for one surface render. Its lifetime is fixed at
 * {@link BOOTSTRAP_TTL_MS}, not caller-chosen: bootstrap data may include a short-lived access token.
 * @complexity O(1).
 */
export function createAdminSurfaceBootstrap<D>(required: { readonly surfaceId: string; readonly data: D; readonly nowMs: number }, _optional: Record<string, never> = {}): AdminSurfaceBootstrap<D> {
  return { surfaceId: required.surfaceId, issuedAt: required.nowMs, expiresAt: required.nowMs + BOOTSTRAP_TTL_MS, data: required.data };
}

/** Headers for the bootstrap response: never stored by the browser or any intermediary cache.
 * @complexity O(1). */
export function adminSurfaceBootstrapHeaders(_required: Record<string, never> = {}, _optional: Record<string, never> = {}): Readonly<Record<string, string>> {
  return {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    Pragma: 'no-cache',
    'X-Content-Type-Options': 'nosniff',
  };
}

/** True while the bootstrap may still be used.
 * @complexity O(1). */
export function isAdminSurfaceBootstrapCurrent(required: { readonly bootstrap: Pick<AdminSurfaceBootstrap, 'expiresAt'>; readonly nowMs: number }, _optional: Record<string, never> = {}): boolean {
  return required.nowMs < required.bootstrap.expiresAt;
}

