          layout: instanceLayout,
          workspaceId: WORKSPACE_ID,
        }),
      (error: unknown) => error instanceof AgentPluginInstallError && error.code === "MANIFEST_INVALID",
    );
    assert.deepEqual(await readdir(layout.root), ["staging"], "rejection must not create a plugin/package directory");
    assert.deepEqual(await readdir(layout.staging), [], "rejection must remove the staging transaction");
  } finally {
    await forceRemove(cwd);
  }
});

test("a published package root is frozen read-only", async () => {
  const { cwd, instanceLayout, layout } = await freshLayout();
  try {
    const archive = new Uint8Array(Buffer.from("archive-bytes-freeze"));
    const digest = createHash("sha256").update(archive).digest("hex");

    const installed = await installAgentPlugin({
      archive,
      expectedSha256: digest,
      archiveReader: reader(validPackageEntries()),
      layout: instanceLayout,
      workspaceId: WORKSPACE_ID,
    });

    const rootMode = (await stat(installed.packageRoot)).mode & 0o777;
    assert.equal(rootMode, 0o555, "package root must carry no write bit after publication");
    for (const relative of ["skills", "skills/ui-ux-design", "plugin.json", "skills/ui-ux-design/SKILL.md"]) {
      const info = await stat(path.join(installed.packageRoot, relative));
      assert.equal(info.mode & 0o222, 0, `${relative} must carry no write bits`);
      assert.equal(info.mode & 0o777, info.isDirectory() ? 0o555 : 0o444, relative);
    }
  } finally {
    await forceRemove(cwd);
  }
});

test("TENANT-GRADE: two workspaces installing the identical archive extract INDEPENDENTLY -- no sharing", async () => {
  const cwd = await mkdtemp(path.join(tmpdir(), "host-agent-plugin-install-test-"));
  try {
    const instanceLayout = resolveAgentPluginLayout({ cwd, env: {} });
    const workspaceA = instanceLayout.forWorkspace({ workspaceId: "11111111-1111-4111-8111-111111111111" });
    const workspaceB = instanceLayout.forWorkspace({ workspaceId: "22222222-2222-4222-8222-222222222222" });

    const archive = new Uint8Array(Buffer.from("archive-bytes-shared-by-two-workspaces"));
    const digest = createHash("sha256").update(archive).digest("hex");

    const { reader: countingReader, extractions } = extractionCountingReader();

    const idA = "11111111-1111-4111-8111-111111111111";
    const idB = "22222222-2222-4222-8222-222222222222";
    // Both installs share the SAME `instanceLayout` object -- only `workspaceId` differs -- proving
    // disjointness comes from `installAgentPlugin`'s own internal `forWorkspace()` call, not from the
    // caller resolving two separate layout values (which is what `workspaceA`/`workspaceB` below are
    // now used for: independent expectations to assert against, not inputs fed back into the call).
    const installedA = await installAgentPlugin({ archive, expectedSha256: digest, archiveReader: countingReader, layout: instanceLayout, workspaceId: idA });
    const installedB = await installAgentPlugin({ archive, expectedSha256: digest, archiveReader: countingReader, layout: instanceLayout, workspaceId: idB });

    // The tenancy property itself: byte-identical content installed by two DIFFERENT workspaces
    // is extracted TWICE, into two entirely disjoint package roots -- the opposite of
    // install.ts's own within-one-workspace dedup test above, and that contrast is the point.
    assert.equal(extractions(), 2, "a second workspace's install must not be satisfied by the first workspace's bytes");
    assert.notEqual(installedA.packageRoot, installedB.packageRoot);
    assert.equal(path.relative(workspaceB.root, installedA.packageRoot).startsWith(".."), true);

    // Deleting workspace A's entire tree must not touch workspace B's copy -- proves the two
    // package roots are not merely different paths but structurally independent on disk.
    await forceRemove(workspaceA.root);
    const stillThere = await readFile(path.join(installedB.packageRoot, "plugin.json"), "utf8");
    assert.equal(stillThere, VALID_MANIFEST);
  } finally {
    await forceRemove(cwd);
  }
});

// ---------------------------------------------------------------------------
// CLOSED, security pass 2026-08-13 (ADS-memory/reports/security/2026-08-13-post-session-security-pass.md,
// Finding 2 -- fixed same day). The tenant-isolation guarantee above used to hold only when every
// caller derived `layout` via `instanceLayout.forWorkspace({ workspaceId: workspaceId })` and never mixed the results
// of two different calls. `AgentPluginWorkspaceLayout` (layout.ts) was a plain interface of four
// string/function fields with no `workspaceId` tag and no back-reference to the instance root it came
// from -- `installAgentPlugin` never re-derived or re-validated `layout` against any expected
// workspace. The two tests below USED TO prove that gap (a hand-stitched layout mixing two real
// workspaces' own directories; a layout never derived from `forWorkspace` at all) -- both installed
// with no error, into the wrong tree, exactly as the original PROVEN GAP test names below still say
// in this section's git history.
//
// THE FIX (`install.ts`): `installAgentPlugin` no longer accepts a pre-resolved
// `AgentPluginWorkspaceLayout` as an input at all. It takes the INSTANCE-level `AgentPluginLayout`
// plus one `workspaceId` string, and calls `layout.forWorkspace({ workspaceId: workspaceId })` itself, exactly once,
// internally -- there is no longer any workspace-shaped parameter here for a caller to stitch
// together. The two tests below are DELIBERATELY REWRITTEN, not deleted or silently renamed, to prove
// the hole is closed rather than merely retired: each keeps the IDENTICAL hostile object literal from
// the original exploit (so this is still evidence against the same attack, not a weaker substitute),
// and proves it now fails two independent ways:
//   1. Honest TypeScript usage cannot even construct the call anymore -- verified with
//      `@ts-expect-error` on a synchronous, side-effect-free type check (never calls
//      `installAgentPlugin`, so there is no runtime behavior riding on this half of the proof; this is
//      confirmed for real by `npx tsc --noEmit`, not merely asserted by a comment).
//   2. Even a caller who defeats the type system with an explicit cast (the realistic worst case:
//      transpiled/loosely-typed JS, or a deliberate `as unknown as`) gets a hard runtime `TypeError`
//      instead of silent cross-workspace publication, because the hostile object has no
//      `forWorkspace` method for `installAgentPlugin`'s first line to call -- this is what actually
//      protects a workspace's data if the type system is bypassed, not merely "the honest path is
//      inconvenient."
//
// Explicitly NOT claimed closed: a caller could still hand `installAgentPlugin` a fully-fabricated
// `AgentPluginLayout` whose OWN `forWorkspace` implementation is malicious (returns mismatched paths
// on purpose). That is no longer "stitching two real, already-resolved values together" (the
// demonstrated bug class this fix targets -- wrong variable capture, a stale cached layout,
// hand-assembly for convenience) but "reimplementing the trusted resolver itself," a materially more
// deliberate act -- the same residual trust every caller-supplied port in this module already carries
// (`archiveReader` is equally free to lie about archive contents). Recorded here rather than silently
// assumed away.
// ---------------------------------------------------------------------------

test("CLOSED: a layout literal stitching workspace A's `packages` onto workspace B's `staging` is now a compile-time type error, and a cast-bypassed call fails at runtime instead of publishing into the wrong tree", async () => {
  const cwd = await mkdtemp(path.join(tmpdir(), "host-agent-plugin-install-test-"));
  try {
    const instanceLayout = resolveAgentPluginLayout({ cwd, env: {} });
    const workspaceA = instanceLayout.forWorkspace({ workspaceId: "11111111-1111-4111-8111-111111111111" });
    const workspaceB = instanceLayout.forWorkspace({ workspaceId: "22222222-2222-4222-8222-222222222222" });

    // The IDENTICAL hostile object from the original gap this test used to prove -- unchanged, so
    // what follows is still proof against the SAME exploit attempt, not a weaker substitute.
    const confusedLayout = {
      root: workspaceA.root,
      packages: workspaceB.packages, // <- workspace B's real package tree
      staging: workspaceB.staging, // <- workspace B's real staging tree
      pluginDataDir: workspaceA.pluginDataDir,
    };

    const archive = new Uint8Array(Buffer.from("archive-bytes-confused-layout"));
    const digest = createHash("sha256").update(archive).digest("hex");

    // Proof 1 (compile-time): `confusedLayout` is not assignable to `InstallAgentPluginRequired["layout"]`
    // anymore (it has no `forWorkspace` method), and `workspaceId` is a required field that's simply
    // absent here. This never calls `installAgentPlugin` -- it only constructs (and immediately
    // discards) a same-shaped argument object, purely so `@ts-expect-error` has something concrete to
    // check. If `install.ts`'s signature ever regressed back to accepting a bare workspace layout,
    // this line would stop producing a type error and `tsc --noEmit` would fail on the now-unused
    // `@ts-expect-error` directive itself -- the proof is self-checking, not just a comment.
    void ((): InstallAgentPluginRequired => ({
      archive,
      expectedSha256: digest,
      archiveReader: reader(validPackageEntries()),
      // @ts-expect-error -- confusedLayout has no forWorkspace method; workspaceId is also missing entirely
      layout: confusedLayout,
    }))();

    // Proof 2 (runtime): the realistic worst case is a caller who bypasses the type system entirely.
    // Even then, `confusedLayout` has no `forWorkspace` method -- `installAgentPlugin`'s very first
    // line now calls `layout.forWorkspace({ workspaceId: workspaceId })`, which throws immediately, before any digest
    // check, mkdir, or extraction happens.
    await assert.rejects(
      () =>
        installAgentPlugin({
          archive,
          expectedSha256: digest,
          archiveReader: reader(validPackageEntries()),
          layout: confusedLayout as unknown as AgentPluginLayout,
          workspaceId: "11111111-1111-4111-8111-111111111111",
        }),
      /forWorkspace is not a function/,
    );

    // And the bytes genuinely never landed anywhere -- neither workspace's tree gained a package.
    assert.deepEqual(await readdir(workspaceA.packages).catch(() => []), []);
    assert.deepEqual(await readdir(workspaceB.packages).catch(() => []), []);
  } finally {
    await forceRemove(cwd);
  }
});

test("CLOSED: a layout never derived from forWorkspace() at all -- arbitrary strings -- is now a compile-time type error, and a cast-bypassed call fails at runtime instead of extracting outside the agent-plugins tree", async () => {
  const cwd = await mkdtemp(path.join(tmpdir(), "host-agent-plugin-install-test-"));
  try {
    // A location that has nothing to do with `<site>/agent-plugins`, `resolveAgentPluginLayout`, or
    // any workspace id at all -- the IDENTICAL hostile shape from the original gap this test used to
    // prove.
    const rogueRoot = path.join(cwd, "somewhere-else-entirely");

    const rogueLayout = {
      root: rogueRoot,
      packages: path.join(rogueRoot, "packages", "sha256"),
      staging: path.join(rogueRoot, "staging"),
      pluginDataDir: (pluginId: string) => path.join(rogueRoot, "data", pluginId),
    };

    const archive = new Uint8Array(Buffer.from("archive-bytes-rogue-layout"));
    const digest = createHash("sha256").update(archive).digest("hex");

    // Proof 1 (compile-time): same shape as the test above -- no `forWorkspace`, no `workspaceId`.
    void ((): InstallAgentPluginRequired => ({
      archive,
      expectedSha256: digest,
      archiveReader: reader(validPackageEntries()),
      // @ts-expect-error -- rogueLayout has no forWorkspace method; workspaceId is also missing entirely
      layout: rogueLayout,
    }))();

    // Proof 2 (runtime): cast-bypassed, exactly like the test above -- `rogueLayout` has no
    // `forWorkspace` either, so the failure mode is identical regardless of whether the hostile
    // object claims to be "two real workspaces confused" or "not a workspace at all."
    await assert.rejects(
      () =>
        installAgentPlugin({
          archive,
          expectedSha256: digest,
          archiveReader: reader(validPackageEntries()),
          layout: rogueLayout as unknown as AgentPluginLayout,
          workspaceId: "11111111-1111-4111-8111-111111111111",
        }),
      /forWorkspace is not a function/,
    );

    // No bytes were written outside the agent-plugins tree at all -- `rogueRoot` was never created.
    await assert.rejects(() => stat(rogueRoot));
  } finally {
    await forceRemove(cwd);
  }
});

src/lifecycle/__tests__/unit/update.unit.source:
import { expect, test } from 'vitest';
import * as fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { createAgentPluginLifecycle, createAgentPluginLayout, type AgentPluginArchiveReaderPort, type AgentPluginLifecyclePorts } from '../../index.js';
import { createAgentPluginUpdateStore, AgentPluginUpdateError, isMissing, type AgentPluginUpdateJournal } from '../../update-store.js';
import { createUpdateModule } from '../../update.js';
import { createInstallModule } from '../../install.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

const workspaceId = 'workspace-a';
const pluginId = 'operator-plugin';
type Layout = ReturnType<typeof createAgentPluginLayout>;
type Harness = Awaited<ReturnType<typeof harness>>;

function archiveInput(layout: Layout, version: string | undefined, extension: Record<string, unknown> = {}, { name = pluginId, salt = '' } = {}) {
  const manifest = { $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name, ...(version ? { version } : {}),
    extensions: { 'org.example.host': extension } };
  const files = { 'plugin.json': JSON.stringify(manifest), [`skills/${name}/SKILL.md`]: `# Version ${version}\nGuidance for ${version}${salt}` };
  const archive = Buffer.from(JSON.stringify(files));
  const archiveReader: AgentPluginArchiveReaderPort = { async *entries() {
    for (const [entryPath, text] of Object.entries(files)) yield { kind: 'file', entryPath, openReadStream: async function* () { yield Buffer.from(text); } };
  } };
  return { archive, archiveReader, expectedSha256: createHash('sha256').update(archive).digest('hex'), layout, workspaceId };
}
async function fixture(run: (h: Harness) => Promise<void>, options: Partial<AgentPluginLifecyclePorts> = {}) {
  const h = await harness(options);
  try { await run(h); } finally { await forceRemove(h.temp); }
}
async function harness(options: Partial<AgentPluginLifecyclePorts> = {}) {
  const temp = await fs.mkdtemp(path.join(os.tmpdir(), 'plugin-update-'));
  const layout = createAgentPluginLayout({ root: path.join(temp, 'plugins') });
  const events: string[] = [];
  const warnings: string[] = [];
  const messages: string[] = [];
  const context: AgentPluginLifecyclePorts = { ...ports, layout, onEvent: ({ event, message }) => {
    if (event.startsWith('agent-plugin-update')) { warnings.push(event); messages.push(message); }
  }, mcpProvisioning: { ...ports.mcpProvisioning,
    provision: async ({ installed }) => { events.push(`provision:${installed.version}`); },
    notifyRosterChanged: async () => { events.push('notify'); },
  }, ...options };
  const api = createAgentPluginLifecycle(context);
  const previous = await api.installAgentPlugin(archiveInput(layout, '1.0.0', { provides: ['cap:old'] }));
  await api.setAgentPluginActivation({ workspaceRoot: layout.forWorkspace({ workspaceId }).root, pluginId, enabled: true, actor: 'owner' });
  const settingsSnapshot = { definitions: [{ key: 'example' }], values: [{ value: 'before' }] };
  const input = { ...archiveInput(layout, '2.0.0'), pluginId, expectedOldDigest: previous.archiveDigest, actor: 'operator:alice',
    snapshotSettings: async () => settingsSnapshot };
  const store = createAgentPluginUpdateStore({ ports: context, workspaceId, pluginId });
  const workspace = layout.forWorkspace({ workspaceId });
  return { api, context, input, previous, settingsSnapshot, store, layout, temp, events, warnings, messages, workspace, workspaceRoot: workspace.root,
    pluginRoot: workspace.pluginRootDir({ pluginId }) };
}
/** A lifecycle over the same layout whose filesystem fails the operations `faults` selects. */
function faulty(h: Harness, faults: { rename?: (to: string) => boolean; readdir?: (dir: string) => boolean; lstat?: (target: string) => boolean }, overrides: Partial<AgentPluginLifecyclePorts> = {}) {
  const filesystem = { ...fs,
    rename: (async (from, to) => { if (faults.rename?.(String(to))) throw Object.assign(new Error(`rename refused: ${path.basename(String(to))}`), { code: 'EIO' }); return fs.rename(from, to); }) as typeof fs.rename,
    readdir: (async (dir: string, options: never) => { if (faults.readdir?.(String(dir))) throw Object.assign(new Error('readdir refused'), { code: 'EACCES' }); return fs.readdir(dir, options); }) as typeof fs.readdir,
    lstat: (async (target: string) => { if (faults.lstat?.(String(target))) throw Object.assign(new Error('lstat refused'), { code: 'EACCES' }); return fs.lstat(target); }) as typeof fs.lstat,
  };
  return createAgentPluginLifecycle({ ...h.context, filesystem, ...overrides });
}
/** Fails only the `nth` matching call, counted from 1. */
function nth(predicate: (value: string) => boolean, n: number) {
  let seen = 0;
  return (value: string) => predicate(value) && ++seen === n;
}
async function liveDigests(h: Harness): Promise<string[]> {
  return (await fs.readdir(h.workspace.pluginPackagesDir({ pluginId }))).sort();
}
async function history(h: Harness): Promise<AgentPluginUpdateJournal[]> {
  const directory = path.join(h.pluginRoot, 'update-history');
  return Promise.all((await fs.readdir(directory)).map(async name => JSON.parse(await fs.readFile(path.join(directory, name), 'utf8'))));
}
async function verdict(h: Harness) {
  return (await h.api.resolveAgentPluginActivation({ workspaceRoot: h.workspaceRoot, pluginId })).verdict;
}
/** The old revision is the only live digest, its guidance resolves, and one rolled-back audit exists. */
async function expectRestored(h: Harness, expectedVerdict: 'active' | 'inactive') {
  expect(await liveDigests(h)).toEqual([h.previous.archiveDigest]);
  expect(await verdict(h)).toBe(expectedVerdict);
  expect(await h.store.read({})).toBeUndefined();
  expect(await history(h)).toEqual([expect.objectContaining({ result: 'rolled-back', actor: 'operator:alice', fromDigest: h.previous.archiveDigest, toDigest: h.input.expectedSha256 })]);
  expect(await fs.readdir(path.join(h.pluginRoot, 'rollback'))).toEqual([]);
  expect((await fs.stat(path.join(h.workspace.pluginPackagesDir({ pluginId }), h.previous.archiveDigest))).mode & 0o777).toBe(0o555);
}

test('enabled update keeps memory and a single live digest; audit is filed at commit; boot collects frozen rollback', async () => {
  await fixture(async h => {
    const memory = h.api.pluginMemory({ workspaceId, pluginId });
    await memory.writeNote({ entryPath: 'preferences.md', text: 'Keep these notes.' });
    const result = await h.api.updateAgentPlugin(h.input);
    expect(result.plugin.version).toBe('2.0.0'); expect(result.enabled).toBe(true); expect(result.alreadyInstalled).toBe(false);
    expect(h.events).toEqual(['provision:2.0.0', 'notify']);
    expect(await liveDigests(h)).toEqual([result.plugin.archiveDigest]);
    expect((await h.api.listInstalledPlugins({ workspaceRoot: h.workspaceRoot })).map(p => p.archiveDigest)).toEqual([result.plugin.archiveDigest]);
    expect(await fs.readFile(path.join(h.workspace.pluginMemoryDir({ pluginId, kind: 'notes' }), 'preferences.md'), 'utf8')).toContain('Keep these notes.');
    // Audit lands at commit, not at the next update or boot.
    expect(await h.store.read({})).toBeUndefined();
    const [audit] = await history(h);
    expect(audit).toMatchObject({ state: 'committed', actor: 'operator:alice', pluginId, fromVersion: '1.0.0', toVersion: '2.0.0',
      fromDigest: h.previous.archiveDigest, toDigest: result.plugin.archiveDigest, result: 'updated', settingsSnapshot: h.settingsSnapshot });
    const historyFile = path.join(h.pluginRoot, 'update-history', `${audit!.transactionId}.json`);
    expect((await fs.stat(historyFile)).mode & 0o777).toBe(0o600);
    // Rollback bytes are retained (frozen, outside package/sha256) until boot.
    const rollbackRoot = h.store.rollbackRoot({ digest: h.previous.archiveDigest });
    expect(rollbackRoot).not.toContain(`${path.sep}sha256${path.sep}`); expect((await fs.stat(rollbackRoot)).mode & 0o777).toBe(0o555);
    const refs = await h.api.resolveAgentPluginRefs({ pluginRefIds: [pluginId], workspaceLayout: h.workspace });
    expect(refs.ok && refs.promptPrefix).toContain('Version 2.0.0');
    await h.api.reconcileAgentPluginUpdates({ workspaceId });
    await h.api.reconcileAgentPluginUpdates({ workspaceId });
    await expect(fs.stat(rollbackRoot)).rejects.toMatchObject({ code: 'ENOENT' });
    expect(await history(h)).toHaveLength(1);
    expect((await h.api.listInstalledPlugins({ workspaceRoot: h.workspaceRoot }))[0]?.version).toBe('2.0.0');
  });
});

test('rollback on MCP activation failure restores old guidance and activation, reprovisions and audits', async () => {
  const provisioned: string[] = [];
  await fixture(async h => {
    await expect(h.api.updateAgentPlugin(h.input)).rejects.toThrow('candidate activation failed');
    expect((await h.api.listInstalledPlugins({ workspaceRoot: h.workspaceRoot })).map(p => p.version)).toEqual(['1.0.0']);
    expect(provisioned).toEqual(['2.0.0', '1.0.0']);
    await expectRestored(h, 'active');
    const refs = await h.api.resolveAgentPluginRefs({ pluginRefIds: [pluginId], workspaceLayout: h.workspace });
    expect(refs.ok && refs.promptPrefix).toContain('Version 1.0.0');
  }, { mcpProvisioning: { ...ports.mcpProvisioning, provision: async ({ installed }) => {
    provisioned.push(installed.version!); if (installed.version === '2.0.0') throw new Error('candidate activation failed');
  } } });
});

test('downgrade, changed digest, bundled provenance and mismatched id refuse without modifying state', async () => {
  await fixture(async h => {
    await expect(h.api.updateAgentPlugin({ ...h.input, expectedOldDigest: '0'.repeat(64) })).rejects.toMatchObject({ code: 'PLUGIN_CHANGED' });
    await expect(h.api.updateAgentPlugin({ ...h.input, pluginId: 'other' })).rejects.toMatchObject({ code: 'PLUGIN_ID_MISMATCH' });
    await expect(h.api.updateAgentPlugin({ ...h.input, ...archiveInput(h.layout, '0.9.0') })).rejects.toMatchObject({ code: 'PLUGIN_DOWNGRADE_REFUSED' });
    await expect(h.api.updateAgentPlugin({ ...h.input, ...archiveInput(h.layout, '2.0.0', { hostRange: '>=99' }) })).rejects.toMatchObject({ code: 'PLUGIN_HOST_INCOMPATIBLE' });
    await h.api.setAgentPluginActivation({ workspaceRoot: h.workspaceRoot, pluginId, enabled: true, actor: 'system:seed' }, { origin: 'bundled' });
    const activationsBefore = await fs.readFile(path.join(h.workspaceRoot, 'activations.json'), 'utf8');
    await expect(h.api.updateAgentPlugin(h.input)).rejects.toMatchObject({ code: 'PLUGIN_BUNDLED' });
    // A bundled plugin never changes state through this path, not even its activation record.
    expect(await fs.readFile(path.join(h.workspaceRoot, 'activations.json'), 'utf8')).toBe(activationsBefore);
    expect(await liveDigests(h)).toEqual([h.previous.archiveDigest]);
    expect(await h.store.read({})).toBeUndefined();
    await expect(fs.stat(path.join(h.pluginRoot, 'rollback'))).rejects.toMatchObject({ code: 'ENOENT' });
    expect(h.events).toEqual([]);
  });
});

test('a plugin that is not installed, or has two live digests, refuses as changed', async () => {
  await fixture(async h => {
    await expect(h.api.updateAgentPlugin({ ...h.input, ...archiveInput(h.layout, '1.0.0', {}, { name: 'absent-plugin' }), pluginId: 'absent-plugin' }))
      .rejects.toMatchObject({ code: 'PLUGIN_CHANGED' });
    const stray = path.join(h.workspace.pluginPackagesDir({ pluginId }), 'f'.repeat(64));
    await fs.cp(h.previous.packageRoot, stray, { recursive: true });
    await expect(h.api.updateAgentPlugin(h.input)).rejects.toMatchObject({ code: 'PLUGIN_CHANGED' });
    expect(await liveDigests(h)).toEqual([h.previous.archiveDigest, 'f'.repeat(64)].sort());
    expect(await h.store.read({})).toBeUndefined();
  });
});

test('an unreadable activation decision refuses before any mutation', async () => {
  await fixture(async h => {
    const file = path.join(h.workspaceRoot, 'activations.json');
    const document = JSON.parse(await fs.readFile(file, 'utf8'));
    document.plugins[pluginId] = 'garbled';
    await fs.writeFile(file, JSON.stringify(document));
    await expect(h.api.updateAgentPlugin(h.input)).rejects.toMatchObject({ code: 'PLUGIN_ACTIVATION_UNKNOWN' });
    expect(await liveDigests(h)).toEqual([h.previous.archiveDigest]);
    expect(await h.store.read({})).toBeUndefined();
  });
});

test('same bytes are a no-op, disabled updates remain off, and missing capabilities warn', async () => {
  await fixture(async h => {
    const same = await h.api.updateAgentPlugin({ ...h.input, ...archiveInput(h.layout, '1.0.0', { provides: ['cap:old'] }) });
    expect(same).toMatchObject({ alreadyInstalled: true, enabled: true, warnings: [] });
    expect(same.plugin.archiveDigest).toBe(h.previous.archiveDigest);
    expect(h.events).toEqual([]); expect(await h.store.read({})).toBeUndefined();
    await h.api.setAgentPluginEnabled({ workspaceId, pluginId, enabled: false, actor: 'owner' });
    const result = await h.api.updateAgentPlugin({ ...h.input, ...archiveInput(h.layout, '2.0.0', { requires: ['missing'] }) });
    expect(result.enabled).toBe(false); expect(result.warnings).toEqual(['Needs missing']);
    expect(await verdict(h)).toBe('inactive');
  });
});

test('a disabled plugin may update to a host-incompatible candidate and stays off; plan warnings pass through', async () => {
  await fixture(async h => {
    await h.api.setAgentPluginEnabled({ workspaceId, pluginId, enabled: false, actor: 'owner' });
    const incompatible = archiveInput(h.layout, '2.0.0', { hostRange: '>=99' });
