import { afterEach, expect, test, vi } from "vitest";
import * as filesystem from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { createSkillFileReader } from "../../index.js";
import type { FilesystemPort } from "../../ports.js";

test("one reader bounds reads and inventory to a skill folder, including symlinks and text admission", async () => {
  const root = await filesystem.mkdtemp(path.join(tmpdir(), "jini-skill-reader-"));
  const skillRoot = path.join(root, "skill");
  await filesystem.mkdir(path.join(skillRoot, "references/nested"), { recursive: true });
  await filesystem.writeFile(path.join(skillRoot, "SKILL.md"), "# Skill\n");
  await filesystem.writeFile(path.join(skillRoot, "references/nested/check.mdx"), "Deep reference.\n");
  await filesystem.writeFile(path.join(skillRoot, "references/foundations.md"), "Exact foundations text.\n");
  await filesystem.writeFile(path.join(root, "outside.md"), "OUTSIDE_CANARY");
  await filesystem.symlink(path.join(root, "outside.md"), path.join(skillRoot, "escape.md"));
  await filesystem.symlink(path.join(root, "outside.md"), path.join(skillRoot, "references/nested/escape.md"));
  await filesystem.symlink(skillRoot, path.join(skillRoot, "cycle"));
  await filesystem.symlink(path.join(skillRoot, "references/foundations.md"), path.join(skillRoot, "alias.md"));
  const reader = createSkillFileReader({ skillRoot, filesystem });
  try {
    const files = ["alias.md", "references/foundations.md", "references/nested/check.mdx"];
    expect(await reader.read({})).toEqual({ text: "# Skill\n", files });
    expect(await reader.read({}, { file: "references/foundations.md" })).toEqual({ text: "Exact foundations text.\n", files });
    expect(await reader.read({}, { file: "alias.md" })).toEqual({ text: "Exact foundations text.\n", files });
    for (const file of ["../outside.md", "references/../SKILL.md", path.join(root, "outside.md"), "C:\\outside.md", "escape.md", "references/nested/escape.md", "missing.md"]) {
      const result = await reader.read({}, { file });
      expect(result.text).toBe("");
      expect(result.files).toEqual(files);
      expect(result.note).toContain("File request refused:");
      expect(result.note).toContain("Valid supporting files: alias.md, references/foundations.md, references/nested/check.mdx.");
      expect(JSON.stringify(result)).not.toContain(root);
      expect(JSON.stringify(result)).not.toContain("OUTSIDE_CANARY");
    }
  } finally { await filesystem.rm(root, { recursive: true, force: true }); }
});

test("extension allowlist, UTF-8, binary detection and exact 256 KiB size boundary govern reads AND inventory", async () => {
  const root = await filesystem.mkdtemp(path.join(tmpdir(), "jini-skill-text-"));
  const reader = createSkillFileReader({ skillRoot: root, filesystem });
  try {
    await filesystem.writeFile(path.join(root, "SKILL.md"), "# Skill");
    await filesystem.writeFile(path.join(root, "limit.txt"), "a".repeat(256 * 1024));
    await filesystem.writeFile(path.join(root, "too-large.md"), "a".repeat(256 * 1024 + 1));
    await filesystem.writeFile(path.join(root, "binary.md"), Buffer.from([0, 1, 2]));
    await filesystem.writeFile(path.join(root, "invalid.md"), Buffer.from([0xff]));
    await filesystem.writeFile(path.join(root, "image.png"), "DISALLOWED_CANARY");
    const extensions = ["md", "mdx", "txt", "json", "yaml", "yml", "ts", "tsx", "js", "jsx", "css", "html", "csv", "svg", "py", "sh"];
    for (const extension of extensions) await filesystem.writeFile(path.join(root, `sample.${extension}`), `Text for ${extension}.\n`);
    const files = ["limit.txt", ...extensions.map(extension => `sample.${extension}`)].sort();
    for (const extension of extensions) expect(await reader.read({}, { file: `sample.${extension}` })).toEqual({ text: `Text for ${extension}.\n`, files });
    expect((await reader.read({}, { file: "limit.txt" })).text).toBe("a".repeat(256 * 1024));
    for (const [file, reason] of [["too-large.md", "256 KiB"], ["binary.md", "binary content"], ["invalid.md", "invalid UTF-8"], ["image.png", "supported text extensions"]] as const) {
      const result = await reader.read({}, { file });
      expect(result.text).toBe("");
      expect(result.files).toEqual(files);
      expect(result.note).toContain(reason);
      expect(JSON.stringify(result)).not.toContain(root);
      expect(JSON.stringify(result)).not.toContain("DISALLOWED_CANARY");
    }
  } finally { await filesystem.rm(root, { recursive: true, force: true }); }
});

const temporaryRoots: string[] = [];
afterEach(async () => { vi.restoreAllMocks(); for (const root of temporaryRoots.splice(0)) await filesystem.rm(root, { recursive: true, force: true }); });
async function skillFolder(files: Record<string, string> = { "SKILL.md": "# Skill" }): Promise<string> {
  const root = await filesystem.mkdtemp(path.join(tmpdir(), "jini-skill-bounds-"));
  temporaryRoots.push(root);
  for (const [file, content] of Object.entries(files)) {
    await filesystem.mkdir(path.dirname(path.join(root, file)), { recursive: true });
    await filesystem.writeFile(path.join(root, file), content);
  }
  return root;
}

test("a directory requested by a text name is refused as not a regular file", async () => {
  const skillRoot = await skillFolder();
  await filesystem.mkdir(path.join(skillRoot, "folder.md"));
  const result = await createSkillFileReader({ skillRoot, filesystem }).read({}, { file: "folder.md" });
  expect(result.note).toBe("File request refused: only regular text files are readable. Valid supporting files: (none). Omit file to request SKILL.md.");
});

test("a file that grows past the cap after its size check is still refused", async () => {
  const skillRoot = await skillFolder({ "SKILL.md": "# Skill", "grows.md": "a".repeat(256 * 1024 + 1) });
  const smallStat = await filesystem.stat(path.join(skillRoot, "SKILL.md"));
  const growing: FilesystemPort = { ...filesystem, open: async (...args: Parameters<FilesystemPort["open"]>) => {
    const handle = await filesystem.open(...args);
    vi.spyOn(handle, "stat").mockResolvedValue(smallStat);
    return handle;
  } };
  const result = await createSkillFileReader({ skillRoot, filesystem: growing }).read({}, { file: "grows.md" });
  expect(result.note).toBe("File request refused: exceeds the 256 KiB text limit; no content returned. Valid supporting files: (none). Omit file to request SKILL.md.");
});

test("a native open failure is refused without reflecting the native message", async () => {
  const skillRoot = await skillFolder();
  const failing: FilesystemPort = { ...filesystem, open: async () => { throw new Error(`EIO: i/o error, open '${skillRoot}/SKILL.md'`); } };
  const result = await createSkillFileReader({ skillRoot, filesystem: failing }).read({});
  expect(result).toEqual({ text: "", files: [], note: "File request refused: file is missing or unreadable. Valid supporting files: (none). Omit file to request SKILL.md." });
});

test("a missing skill folder reports an incomplete inventory alongside the refusal", async () => {
  const skillRoot = path.join(await skillFolder(), "absent");
  const result = await createSkillFileReader({ skillRoot, filesystem }).read({});
  expect(result).toEqual({ text: "", files: [], note: "File request refused: file is missing, unreadable, or resolves outside this skill folder. Valid supporting files: (none). Omit file to request SKILL.md. Supporting-file inventory is incomplete: traversal limit reached or a directory is unreadable." });
});

test("an inventory deeper than 32 directories is marked incomplete", async () => {
  const deep = `${Array.from({ length: 33 }, (_, index) => `d${index}`).join("/")}/deep.md`;
  const skillRoot = await skillFolder({ "SKILL.md": "# Skill", "top.md": "top", [deep]: "deep" });
  const result = await createSkillFileReader({ skillRoot, filesystem }).read({});
  expect(result).toEqual({ text: "# Skill", files: ["top.md"], note: "Supporting-file inventory is incomplete: traversal limit reached or a directory is unreadable." });
});

test("the 4096-entry inventory budget stops at the boundary, including a directory reached with no budget left", async () => {
  const skillRoot = await skillFolder();
  // SKILL.md plus 4094 files leaves one entry: directory `g` spends it, so its walk and file `h` are cut off.
  await Promise.all(Array.from({ length: 4094 }, (_, index) => filesystem.writeFile(path.join(skillRoot, `f${String(index).padStart(4, "0")}`), "")));
  await filesystem.mkdir(path.join(skillRoot, "g"));
  await filesystem.writeFile(path.join(skillRoot, "g", "inside.md"), "inside");
  await filesystem.writeFile(path.join(skillRoot, "h.md"), "after");
  const result = await createSkillFileReader({ skillRoot, filesystem }).read({});
  expect(result).toEqual({ text: "# Skill", files: [], note: "Supporting-file inventory is incomplete: traversal limit reached or a directory is unreadable." });
}, 30_000);

test("the inventory lists files in code-unit order whatever the directory order", async () => {
  const skillRoot = await skillFolder({ "SKILL.md": "# Skill", "b.md": "b", "B.md": "B", "a.md": "a", "c/z.md": "z" });
  expect((await createSkillFileReader({ skillRoot, filesystem }).read({})).files).toEqual(["B.md", "a.md", "b.md", "c/z.md"]);
});

test("a text-named symlink to a contained non-text file is refused and not advertised", async () => {
  const skillRoot = await skillFolder({ "SKILL.md": "# Skill", "image.png": "DISALLOWED_CANARY" });
  await filesystem.symlink(path.join(skillRoot, "image.png"), path.join(skillRoot, "alias.md"));
  const result = await createSkillFileReader({ skillRoot, filesystem }).read({}, { file: "alias.md" });
  expect(result).toEqual({ text: "", files: [], note: "File request refused: file is missing, unreadable, or resolves outside this skill folder. Valid supporting files: (none). Omit file to request SKILL.md." });
});

test("a native read failure on an opened file is refused without reflecting the native message", async () => {
  const skillRoot = await skillFolder();
  const failing: FilesystemPort = { ...filesystem, open: async (...args: Parameters<FilesystemPort["open"]>) => {
    const handle = await filesystem.open(...args);
    vi.spyOn(handle, "read").mockRejectedValue(new Error(`EIO: i/o error, read '${skillRoot}/SKILL.md'`));
    return handle;
  } };
  const result = await createSkillFileReader({ skillRoot, filesystem: failing }).read({});
  expect(result).toEqual({ text: "", files: [], note: "File request refused: file is missing or unreadable. Valid supporting files: (none). Omit file to request SKILL.md." });
});

src/admin-surfaces/__tests__/external-li.source:
/**
 * @file Security pins (phase A) for host-mediated external links: a surface may only declare bare
 * https origins (bounded, unique), and an `open-link` message reaches the host's opener only from
 * this mount's frame, with this mount's nonce, for a well-formed https URL on a declared origin.
 * Every refusal names a code and never echoes the URL; the opener receives the parser's normalized
 * form, so the host never re-parses a string the gate judged differently.
 */
import { describe, expect, test } from 'vitest';
import { createAdminSurfaceClient } from '../surface-client.js';
import { openAdminSurfaceLink, parseAdminSurfacesFile, type AdminSurfaceDescriptor, type AdminSurfaceMessageEvent, type AdminSurfaceMountRecord } from '../index.js';

const surface = (overrides: Record<string, unknown> = {}) => ({ id: 'settings', title: 'Settings', entry: 'surface/index.html', ...overrides });
const raw = (overrides: Record<string, unknown>) => JSON.stringify({ schemaVersion: 1, surfaces: [surface(overrides)] });
function parseOne(overrides: Record<string, unknown> = {}): AdminSurfaceDescriptor {
  const parsed = parseAdminSurfacesFile({ raw: raw(overrides) });
  if (!parsed.ok) throw new Error(parsed.reason);
  return parsed.descriptors[0]!;
}
const reasonFor = (overrides: Record<string, unknown>) => {
  const parsed = parseAdminSurfacesFile({ raw: raw(overrides) });
  return parsed.ok ? 'accepted' : parsed.reason;
};

describe('declared link origins', () => {
  test('bare https origins are kept as declared', () => {
    expect(parseOne({ linkOrigins: ['https://accounts.example.com', 'https://docs.example.com:8443'] }).linkOrigins).toEqual(['https://accounts.example.com', 'https://docs.example.com:8443']);
  });
  test.each(['http://accounts.example.com', 'https://*.example.com', 'https://accounts.example.com/path', 'https://127.0.0.1', 'javascript:alert(1)', 'data:text/html,x', 'https://accounts.example.com:443', 'https://user@accounts.example.com', 42])('origin %j is refused', (origin) => {
    expect(reasonFor({ linkOrigins: [origin] })).toBe('surfaces[0].linkOrigins[0] must be a unique bare https origin (no wildcards, paths or keywords)');
  });
  test('a duplicate origin is refused', () => {
    expect(reasonFor({ linkOrigins: ['https://a.example.com', 'https://a.example.com'] })).toBe('surfaces[0].linkOrigins[1] must be a unique bare https origin (no wildcards, paths or keywords)');
  });
  test('more than 8 origins are refused', () => {
    const origins = Array.from({ length: 9 }, (_, index) => `https://h${index}.example.com`);
    expect(reasonFor({ linkOrigins: origins })).toBe('surfaces[0].linkOrigins must be an array of at most 8');
  });
});

describe('open-link gate', () => {
  const frame = {};
  const mount: AdminSurfaceMountRecord = { mountId: 'nonce-1', frame, descriptor: parseOne({ linkOrigins: ['https://accounts.example.com'] }) };
  const message = (overrides: Record<string, unknown> = {}) => ({ protocol: 'jini.admin-surface', version: 1, kind: 'open-link', mountId: 'nonce-1', requestId: 'r1', url: 'https://accounts.example.com/permissions', ...overrides });
  const event = (overrides: Partial<AdminSurfaceMessageEvent> = {}, data: unknown = message()): AdminSurfaceMessageEvent => ({ origin: 'null', source: frame, data, ...overrides });
  function opener(optional: { readonly fails?: boolean } = {}) {
    const opened: string[] = [];
    const openLink = async ({ url }: { readonly url: string }) => { if (optional.fails) throw new Error('shell refused https://accounts.example.com/secret'); opened.push(url); };
    return { opened, openLink };
  }
  const refusal = (code: string, text: string, retryable = false) => ({
    ok: false, refused: code,
    response: { protocol: 'jini.admin-surface', version: 1, kind: 'action-response', mountId: 'nonce-1', requestId: 'r1', ok: false, error: { code, message: text, retryable } },
  });

  test('a declared https link is handed to the host opener in normalized form and answered', async () => {
    const { opened, openLink } = opener();
    const verdict = await openAdminSurfaceLink({ event: event({}, message({ url: 'https://ACCOUNTS.example.com:443/permissions?x=1' })), mount, openLink });
    expect(opened).toEqual(['https://accounts.example.com/permissions?x=1']);
    expect(verdict).toEqual({ ok: true, url: 'https://accounts.example.com/permissions?x=1', response: { protocol: 'jini.admin-surface', version: 1, kind: 'action-response', mountId: 'nonce-1', requestId: 'r1', ok: true, result: null } });
  });
  test('an undeclared origin is refused without opening or echoing the URL', async () => {
    const { opened, openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message({ url: 'https://evil.example.net/phish' })), mount, openLink }))
      .toEqual(refusal('link-undeclared', 'This surface did not declare that link destination.'));
    expect(opened).toEqual([]);
  });
  test('a surface that declares no link origins can open nothing', async () => {
    const { opened, openLink } = opener();
    const bare: AdminSurfaceMountRecord = { ...mount, descriptor: parseOne() };
    expect(await openAdminSurfaceLink({ event: event(), mount: bare, openLink })).toEqual(refusal('link-undeclared', 'This surface did not declare that link destination.'));
    expect(opened).toEqual([]);
  });
  test.each(['http://accounts.example.com/permissions', 'javascript:alert(document.domain)', 'data:text/html,<script>alert(1)</script>', 'JAVASCRIPT://accounts.example.com/%0aalert(1)'])('non-https link %j is refused', async (url) => {
    const { opened, openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message({ url })), mount, openLink })).toEqual(refusal('link-not-https', 'Only https links can be opened.'));
    expect(opened).toEqual([]);
  });
  test.each(['not a url', 'https://user:pass@accounts.example.com/permissions'])('malformed or credential-carrying link %j is refused', async (url) => {
    const { opened, openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message({ url })), mount, openLink })).toEqual(refusal('link-invalid', 'That link is not a valid web address.'));
    expect(opened).toEqual([]);
  });
  test('a link longer than 2048 characters is refused', async () => {
    const { opened, openLink } = opener();
    const url = `https://accounts.example.com/${'a'.repeat(2048 - 'https://accounts.example.com/'.length + 1)}`;
    expect(await openAdminSurfaceLink({ event: event({}, message({ url })), mount, openLink })).toEqual(refusal('link-too-long', 'The link is too long.'));
    expect(opened).toEqual([]);
  });
  test('a link of exactly 2048 characters is opened', async () => {
    const { opened, openLink } = opener();
    const url = `https://accounts.example.com/${'a'.repeat(2048 - 'https://accounts.example.com/'.length)}`;
    await openAdminSurfaceLink({ event: event({}, message({ url })), mount, openLink });
    expect(opened).toEqual([url]);
  });
  test('a wrong mount nonce is ignored and opens nothing', async () => {
    const { opened, openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message({ mountId: 'nonce-2' })), mount, openLink })).toEqual({ ok: false, ignored: 'mount-mismatch' });
    expect(opened).toEqual([]);
  });
  test('another sandboxed frame is ignored', async () => {
    const { openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({ source: {} }), mount, openLink })).toEqual({ ok: false, ignored: 'source-mismatch' });
  });
  test('a non-sandboxed origin is ignored', async () => {
    const { openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({ origin: 'https://accounts.example.com' }), mount, openLink })).toEqual({ ok: false, ignored: 'origin-mismatch' });
  });
  test.each([
    ['an action request', { kind: 'action-request' }],
    ['a non-string url', { url: 42 }],
    ['a malformed request id', { requestId: 'has space' }],
  ])('%s is not an open-link message', async (_label, overrides) => {
    const { openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, message(overrides)), mount, openLink })).toEqual({ ok: false, ignored: 'not-an-open-link' });
  });
  test.each(['open-link', null])('non-object message data %j is not an open-link message', async (data) => {
    const { openLink } = opener();
    expect(await openAdminSurfaceLink({ event: event({}, data), mount, openLink })).toEqual({ ok: false, ignored: 'not-an-open-link' });
  });
  test('an opener failure is answered as retryable without its raw text', async () => {
    const { openLink } = opener({ fails: true });
    expect(await openAdminSurfaceLink({ event: event(), mount, openLink })).toEqual(refusal('link-failed', 'The host could not open the link. Try again.', true));
  });
});

test('the surface client posts open-link only to the host origin learned from init and rejects with the host refusal', async () => {
  const posted: Array<{ readonly message: unknown; readonly targetOrigin: string }> = [];
  const parent = { postMessage(message: unknown, targetOrigin: string) { posted.push({ message, targetOrigin }); } };
  let deliver: (event: { readonly origin: string; readonly source: unknown; readonly data: unknown }) => void = () => {};
  const client = createAdminSurfaceClient({ parent, listen: (handler) => { deliver = handler; return () => {}; } });
  const base = { protocol: 'jini.admin-surface', version: 1, mountId: 'nonce-1' };
  deliver({ origin: 'https://host.example.com', source: parent, data: { ...base, kind: 'init' } });
  const pending = client.openLink({ url: 'https://elsewhere.example.net/' });
  await Promise.resolve();
  expect(posted).toEqual([{ message: { ...base, kind: 'open-link', requestId: 'r1', url: 'https://elsewhere.example.net/' }, targetOrigin: 'https://host.example.com' }]);
  deliver({ origin: 'https://host.example.com', source: parent, data: { ...base, kind: 'action-response', requestId: 'r1', ok: false, error: { code: 'link-undeclared', message: 'This surface did not declare that link destination.', retryable: false } } });
  await expect(pending).rejects.toMatchObject({ name: 'AdminSurfaceCallError', code: 'link-undeclared' });
  client.close();
});

