import { withFileLock } from "@jini-ai/platform/fs/file-lock";
import * as nativeFilesystem from "node:fs/promises";
import { test, expect } from 'vitest';
import { validatePluginManifest, validateMcpManifest, isPluginManifest, isMcpManifest } from '../index.js';
import { createAgentPluginLifecycle, createAgentPluginLayout, parseAgentPluginManifest, fetchAgentPluginArchive } from '../lifecycle/index.js';
import { createNodeAgentPluginEffects } from '../lifecycle/node.js';
import { ports } from '../lifecycle/__tests__/test-support.js';
import { mkdtemp } from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { forceRemove } from '../lifecycle/__tests__/fixtures/force-remove.js';

test('object validators preserve legacy structural validation', () => {
  for (const value of [null, [], {}, { name: '' }, { name: 'toolkit' }]) {
    expect(validatePluginManifest({ value })).toBe(isPluginManifest(value));
    expect(validateMcpManifest({ value })).toBe(isMcpManifest(value));
  }
  expect(validateMcpManifest({ value: { mcpServers: {} } })).toBe(true);
});

test('identity namespace injection preserves the legacy plugin format and selects host metadata', () => {
  const value = {
    $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'toolkit',
    extensions: {
      tovu: { id: 'legacy/toolkit', provides: ['source-control'] },
      example: { id: 'example/toolkit', provides: ['deploy-target:fly'] },
    },
  };
  expect(parseAgentPluginManifest({ value })).toMatchObject({
    ok: true, manifest: { id: 'legacy/toolkit', provides: ['source-control'] }, warnings: [],
  });
  expect(parseAgentPluginManifest({ value }, { identityNamespace: 'example' })).toMatchObject({
    ok: true, manifest: { id: 'example/toolkit', provides: ['deploy-target:fly'] }, warnings: [],
  });
  const invalid = { ...value, extensions: { ...value.extensions, example: { id: 'invalid' } } };
  expect(validatePluginManifest({ value: invalid })).toBe(true);
  expect(validatePluginManifest({ value: invalid }, { identityNamespace: 'example' })).toBe(false);
  expect(parseAgentPluginManifest({ value: invalid }, { identityNamespace: 'example' })).toEqual({
    ok: false, errors: ['Plugin id must have the form publisher/name (lowercase letters, digits, dots and hyphens).'],
  });
});

test('strict parser preserves standard author objects and legacy author strings', () => {
  const author = { name: 'Example', email: 'author@example.com', url: 'https://example.com' };
  for (const value of [author, 'Example']) {
    const result = parseAgentPluginManifest({ value: {
      $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'toolkit', author: value,
    } });
    expect(result).toMatchObject({ ok: true, manifest: { author: value } });
  }
});

// REGRESSION: fails if lifecycle calls fs/promises.open with a wrapped path object.
test('archive installation accepts native filesystem effects through the public facade', async () => {
  const root = await mkdtemp(path.join(os.tmpdir(), 'plugin-contract-'));
  const effects = createNodeAgentPluginEffects({});
  const seen: string[] = [];
  const api = createAgentPluginLifecycle({ ...ports, ...effects,
    layout: createAgentPluginLayout({ root }),
    filesystem: { ...effects.filesystem, open: async (...args: Parameters<typeof nativeFilesystem.open>) => {
      expect(typeof args[0]).toBe('string');
      seen.push(String(args[0]));
      return effects.filesystem.open(...args);
    } },
  });
  try {
    const sourceDir = path.join(root, 'source');
    await effects.filesystem.mkdir(sourceDir, { recursive: true });
    const handle = await effects.filesystem.open(path.join(sourceDir, 'plugin.json'), 'w');
    await handle.writeFile(JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'toolkit' }), 'utf8');
    await handle.close();
    const packed = await api.packAgentPluginDirectory({ sourceDir });
    const reader = api.createBundledSourceArchiveReader({});
    const installed = await api.installAgentPlugin({ archive: packed.bytes, expectedSha256: packed.sha256,
      archiveReader: { entries: required => { expect(required.archive).toBe(packed.bytes); return reader.entries(required); } },
      layout: createAgentPluginLayout({ root }),
      workspaceId: 'example',
    });
    expect(installed.pluginId).toBe('toolkit');
    expect(installed.files).toEqual(['plugin.json']);
    expect(seen.some(p => p.endsWith('plugin.json'))).toBe(true);
  } finally { await forceRemove(root); }
});

test('download passes URL and redirect policy as separate objects to the fetch port', async () => {
  const requests: unknown[] = [];
  const result = await fetchAgentPluginArchive({ url: 'https://example.com/plugin.zip',
    outboundGuard: { assertAllowed: async () => {} },
    fetch: async (required, optional) => { requests.push([required, optional]); return new Response(new Uint8Array([4, 5])); },
  });
  expect(requests).toEqual([[{ url: 'https://example.com/plugin.zip' }, { redirect: 'manual' }]]);
  expect(Array.from(result.archive)).toEqual([4, 5]);
});

test('public callbacks receive objects, including lock ownership checks', async () => {
  const api = createAgentPluginLifecycle(ports);
  const received: unknown[] = [];
  const items = [{ id: 'plugin-a' }];
  expect(api.filterActiveAgentPlugins({ activations: { schemaVersion: 1, plugins: {} }, items,
    pluginIdOf: required => { received.push(required); return required.item.id; },
  })).toEqual(items);
  expect(received).toEqual([{ item: items[0] }]);
  const root = await mkdtemp(path.join(os.tmpdir(), 'plugin-lock-contract-'));
  try {
    const result = await withFileLock({ lockPath: path.join(root, 'lock'),
      run: async lock => { await lock.assertHeld({}); return lock.lockPath; },
    });
    expect(api).not.toHaveProperty('withExclusiveFileLock');
    expect(result).toBe(path.join(root, 'lock'));
  } finally { await forceRemove(root); }
});

src/lifecycle/__tests__/unit/package-pat.source:
import assert from "node:assert/strict";
import { normalizePackageEntryPath } from "../test-support.js";
import { mkdir, mkdtemp, realpath, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "../legacy-test.js";

import { assertContainedOnDisk } from "../test-support.js";
import { PackagePathViolation } from "../../package-paths.js";

/**
 * @file Path-safety primitive shared by extraction (`install.ts`) and any future preview read.
 *
 * The Agent Plugins spec's own MUST is a filesystem-RESOLVED containment check, not a lexical one:
 * "the filesystem-resolved path MUST remain within the filesystem-resolved plugin root... clients
 * MUST reject package paths that resolve outside it" (agent-plugins.org spec v1.0.0). These tests
 * cover both the cheap lexical rejection (no filesystem call needed) and the realpath-based rejection
 * (a lexically clean path that is, or passes through, a symlink planted by a hostile archive).
 */

test("normalizePackageEntryPath: rejects a lexical '..' segment", () => {
  assert.throws(() => normalizePackageEntryPath("../outside"), PackagePathViolation);
});

test("normalizePackageEntryPath: rejects an absolute POSIX path", () => {
  assert.throws(() => normalizePackageEntryPath("/etc/passwd"), PackagePathViolation);
});

test("normalizePackageEntryPath: rejects a Windows drive-absolute path", () => {
  assert.throws(() => normalizePackageEntryPath("C:\\Windows\\System32"), PackagePathViolation);
});

test("normalizePackageEntryPath: rejects a NUL byte", () => {
  assert.throws(() => normalizePackageEntryPath("skills/a\0/SKILL.md"), PackagePathViolation);
});

test("normalizePackageEntryPath: accepts a normal relative path unchanged", () => {
  assert.equal(normalizePackageEntryPath("skills/a/SKILL.md"), "skills/a/SKILL.md");
});

test("normalizePackageEntryPath: normalizes backslashes to forward slashes", () => {
  assert.equal(normalizePackageEntryPath("skills\\a\\SKILL.md"), "skills/a/SKILL.md");
});

test("assertContainedOnDisk: accepts a path that resolves inside the root", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "host-package-paths-test-"));
  try {
    await mkdir(path.join(root, "skills", "a"), { recursive: true });
    const resolved = await assertContainedOnDisk(root, "skills/a/SKILL.md");
    // Compared against the REALPATH'd root, not the raw tmpdir() string: on macOS `/var` is itself
    // a symlink to `/private/var`, and this function's whole job is to resolve through symlinks —
    // asserting against the un-resolved root would fail for a reason unrelated to what's under test.
    const realRoot = await realpath(root);
    assert.equal(resolved, path.join(realRoot, "skills", "a", "SKILL.md"));
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

test("assertContainedOnDisk: rejects a path whose PARENT is a symlink escaping the root", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "host-package-paths-test-"));
  const outside = await mkdtemp(path.join(tmpdir(), "host-package-paths-outside-"));
  try {
    // A hostile archive plants a symlinked directory inside the root that resolves elsewhere on
    // disk; a later, lexically-innocent-looking entry underneath it must still be rejected because
    // the REAL, resolved path escapes root — this is exactly the two-step zip-slip vector (a
    // symlink entry, then a second entry that walks through it) the spec's MUST clause exists for.
    await symlink(outside, path.join(root, "escape"));
    await assert.rejects(
      () => assertContainedOnDisk(root, "escape/planted.txt"),
      PackagePathViolation,
    );
  } finally {
    await rm(root, { recursive: true, force: true });
    await rm(outside, { recursive: true, force: true });
  }
});

test("assertContainedOnDisk: rejects when the target ITSELF is a symlink escaping the root", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "host-package-paths-test-"));
  const outsideFile = await mkdtemp(path.join(tmpdir(), "host-package-paths-outside-"));
  const outsideTarget = path.join(outsideFile, "secret.txt");
  await writeFile(outsideTarget, "secret");
  try {
    await symlink(outsideTarget, path.join(root, "leak.txt"));
    await assert.rejects(
      () => assertContainedOnDisk(root, "leak.txt"),
      PackagePathViolation,
    );
  } finally {
    await rm(root, { recursive: true, force: true });
    await rm(outsideFile, { recursive: true, force: true });
  }
});

test("assertContainedOnDisk: re-resolves the root fresh on every call (no cached-root TOCTOU)", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "host-package-paths-test-"));
  try {
    await mkdir(path.join(root, "skills"), { recursive: true });
    // A plain, real subdirectory resolves fine even though `root` itself is re-realpath'd each call.
    const resolved = await assertContainedOnDisk(root, "skills");
    const realRoot = await realpath(root);
    assert.equal(resolved, path.join(realRoot, "skills"));
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

